import{l as m,r as y,j as e,e as h}from"./index-C-MtFuSr.js";import{r as f,f as b,a as p,i as g}from"./masteryProgress-17Fuzyq9.js";const u=[{stage:2,level:"B1 → B2",title:"Precision and information structure",titleZh:"精确表达与信息结构",thesis:"Move beyond correct sentences: control what the reader notices first, what remains backgrounded, and how strongly a claim lands.",thesisZh:"不止写出正确句子，还要控制读者先注意什么、哪些信息退居背景，以及观点以多强的力度落下。",units:[{unit:1,title:"Given before new",titleZh:"已知信息先行",capability:"Shape topic–comment flow across sentences",capabilityZh:"控制跨句的主题—述位推进",specimen:"The deadline changed. What surprised us was the reason.",move:"information flow"},{unit:2,title:"Clefts without clutter",titleZh:"克制地使用强调句",capability:"Use it-clefts and wh-clefts only when contrast earns them",capabilityZh:"仅在真正需要对比时使用 it/wh 强调结构",specimen:"It was the timing—not the cost—that changed the decision.",move:"focus"},{unit:3,title:"Inversion and restraint",titleZh:"倒装与分寸",capability:"Deploy negative inversion without sounding theatrical",capabilityZh:"使用否定倒装，同时避免戏剧腔",specimen:"Rarely does a small omission carry such a large consequence.",move:"emphasis"}]},{stage:3,level:"B2 → C1",title:"Stance, evidence, and intellectual honesty",titleZh:"立场、证据与智识诚实",thesis:"Calibrate certainty, distinguish observation from inference, and make disagreement rigorous without making it needlessly hostile.",thesisZh:"校准确定性，区分观察与推断，让分歧保持严谨而不必带有敌意。",units:[{unit:1,title:"The certainty dial",titleZh:"确定性旋钮",capability:"Choose among suggests, indicates, demonstrates, and establishes",capabilityZh:"区分 suggests、indicates、demonstrates 与 establishes",specimen:"The pattern suggests a constraint; it does not establish a cause.",move:"epistemic force"},{unit:2,title:"Responsible hedging",titleZh:"负责任的限定",capability:"Hedge the claim, not the writer's courage",capabilityZh:"限定观点边界，而不是削弱写作者的勇气",specimen:"Under these conditions, the estimate is likely to be conservative.",move:"scope"},{unit:3,title:"Concede, then turn",titleZh:"让步之后推进",capability:"Represent an opposing case fairly before rebutting it",capabilityZh:"先公允呈现反方，再作反驳",specimen:"That objection is persuasive on cost, but it overlooks reversibility.",move:"concession"}]},{stage:4,level:"C1 → C2",title:"Register, rhythm, and rhetorical control",titleZh:"语域、节奏与修辞控制",thesis:"Say the same underlying thing as a briefing, an essay, a difficult email, or a public explanation—without losing precision.",thesisZh:"把同一核心内容写成简报、文章、棘手邮件或公众说明，同时不损失精确度。",units:[{unit:1,title:"Register is a relationship",titleZh:"语域是一种关系",capability:"Shift social distance without merely swapping vocabulary",capabilityZh:"改变社会距离，而不只是替换词汇",specimen:"Could you revisit the assumption behind that estimate?",move:"register"},{unit:2,title:"Sentence music",titleZh:"句子的音乐性",capability:"Use length, stress, and punctuation to guide attention",capabilityZh:"用句长、重音和标点引导注意力",specimen:"The plan was plausible, well funded, and wrong.",move:"rhythm"},{unit:3,title:"Lexical prosody",titleZh:"词汇韵律与搭配倾向",capability:"Notice the evaluative company a word habitually keeps",capabilityZh:"识别词语惯常搭配所携带的评价色彩",specimen:"The policy triggered concern but prompted a useful review.",move:"collocation"}]},{stage:5,level:"C2+",title:"The editor's room",titleZh:"资深编辑室",thesis:"Diagnose prose at paragraph scale: ambiguity, hidden agency, false coherence, needless abstraction, and voice that disappears under polish.",thesisZh:"在段落尺度诊断歧义、隐藏的施事者、虚假的连贯、无谓抽象，以及被过度润色抹去的个人声音。",units:[{unit:1,title:"Ambiguity under pressure",titleZh:"高压语境中的歧义",capability:"Find readings that grammar permits but context cannot afford",capabilityZh:"找出语法允许、但语境承担不起的多重解读",specimen:"We discussed the review with the director who had raised concerns.",move:"ambiguity"},{unit:2,title:"Agency and accountability",titleZh:"施事者与责任",capability:"Choose passive voice deliberately and restore agents when stakes demand it",capabilityZh:"有意识地选择被动语态，并在责任攸关时恢复施事者",specimen:"The threshold was changed after the results were reviewed.",move:"agency"},{unit:3,title:"Compression without flattening",titleZh:"压缩而不扁平",capability:"Cut a third of the words while preserving qualification and voice",capabilityZh:"删去三分之一文字，同时保留限定条件和个人声音",specimen:"Concise prose is not prose from which every trace of a person has vanished.",move:"editing"}]},{stage:6,level:"Daily Life Studio",title:"High-stakes everyday English",titleZh:"高难度日常英语工作室",thesis:"Apply advanced English where relationships and outcomes are real: meetings, difficult email, disagreement, service recovery, apology, and personal boundaries.",thesisZh:"把高阶英语用于关系与结果都真实的场合：会议、棘手邮件、分歧、投诉协商、道歉修复和个人边界。",units:[{unit:1,title:"Enter the meeting",titleZh:"在会议中自然插话",capability:"Interrupt without surrendering either urgency or respect",capabilityZh:"插话时同时保留紧迫性与尊重",specimen:"Could I come in on that point before we move on?",move:"turn-taking"},{unit:2,title:"The difficult email",titleZh:"写一封棘手邮件",capability:"Separate the record, the impact, and the requested next action",capabilityZh:"区分事实记录、影响与下一步请求",specimen:"The file arrived after the agreed deadline, so could you confirm the revised date?",move:"email"},{unit:3,title:"Disagree and keep working",titleZh:"表达分歧并继续合作",capability:"Challenge a proposal without turning the person into the problem",capabilityZh:"挑战方案，而不把提出方案的人变成问题",specimen:"I see the speed advantage; my concern is what happens when demand spikes.",move:"disagreement"},{unit:4,title:"Complain toward a remedy",titleZh:"让投诉走向解决方案",capability:"Document a service failure and ask for a proportionate remedy",capabilityZh:"记录服务失败并提出适度补救要求",specimen:"The replacement has the same fault, so I’m asking for a refund rather than another exchange.",move:"service recovery"},{unit:5,title:"Repair an apology",titleZh:"完成真正的道歉修复",capability:"Own impact without hiding behind intention or a conditional apology",capabilityZh:"承担影响，不躲在意图或条件式道歉之后",specimen:"I interrupted you twice. That made it harder for you to finish your point. I’m sorry.",move:"repair"},{unit:6,title:"Set a warm boundary",titleZh:"设定温和而清晰的边界",capability:"Decline, preserve the relationship, and avoid opening a negotiation you do not want",capabilityZh:"拒绝、保留关系，同时不开启自己不想要的谈判",specimen:"I can’t host this weekend, but I’d be glad to meet for lunch next week.",move:"boundaries"}]},{stage:7,level:"City Life Lab",title:"Navigate the city with clarity",titleZh:"清晰应对城市生活",thesis:"Handle the moments where vague English creates real costs: housing problems, healthcare conversations, and disrupted journeys.",thesisZh:"应对含糊表达会带来真实代价的时刻：住房问题、就医沟通与行程中断。",units:[{unit:1,title:"Document a housing problem",titleZh:"说明住房问题",capability:"Locate the fault, distinguish observation from cause, and request a dated action",capabilityZh:"定位故障、区分观察与原因，并请求有日期的行动",specimen:"There is a damp patch below the bedroom window; could you arrange an inspection by Friday?",move:"housing"},{unit:2,title:"Describe symptoms precisely",titleZh:"准确描述症状",capability:"Give onset, pattern, and functional impact without guessing a diagnosis",capabilityZh:"说明起始时间、变化规律和功能影响，不自行猜测诊断",specimen:"The pain started on Tuesday, becomes sharper when I lift things, and is limiting my grip.",move:"healthcare"},{unit:3,title:"Recover a disrupted journey",titleZh:"处理行程中断",capability:"State the original itinerary, the disruption, and the concrete option you need",capabilityZh:"说明原行程、中断事实与需要的具体方案",specimen:"The cancellation means I’ll miss my connection; could you route me via Bristol instead?",move:"transit"}]},{stage:8,level:"Community Life Lab",title:"Ask clearly beyond your front door",titleZh:"走出家门，清楚提出需求",thesis:"Protect everyday relationships and practical outcomes when speaking with neighbors, restaurant staff, and lost-property teams.",thesisZh:"与邻居、餐厅员工和失物招领人员沟通时，同时保护日常关系和实际结果。",units:[{unit:1,title:"Negotiate quiet with a neighbor",titleZh:"与邻居协商安静时间",capability:"Name a recurring pattern and impact before proposing a workable agreement",capabilityZh:"先说明重复规律和影响，再提出可执行的约定",specimen:"The music has carried into my bedroom after eleven three nights this week; could we keep it lower after ten thirty?",move:"neighbor negotiation"},{unit:2,title:"Make a dietary need unambiguous",titleZh:"清楚说明饮食需求",capability:"Distinguish a safety requirement from preference and confirm ingredients and preparation",capabilityZh:"区分安全要求与偏好，并确认配料和制作方式",specimen:"I have a sesame allergy. Could you check the sauce and garnish, and whether the dish can be prepared separately?",move:"dietary needs"},{unit:3,title:"Report a lost item",titleZh:"准确报告遗失物品",capability:"Combine identity, a distinctive feature, last known location, and follow-up details",capabilityZh:"组合物品身份、独特特征、最后位置和跟进信息",specimen:"It’s a dark-green canvas backpack with an ochre tag; I last had it by the reading-room window around four.",move:"lost property"}]},{stage:9,level:"Everyday Admin Lab",title:"Resolve the record, not just the frustration",titleZh:"处理记录，而不只表达不满",thesis:"Use transaction, delivery, and billing records to isolate what is wrong, protect what is still valid, and secure a confirmable next step.",thesisZh:"利用交易、配送和账单记录定位错误，保留仍然有效的部分，并取得可确认的下一步。",units:[{unit:1,title:"Challenge an unknown card payment",titleZh:"处理陌生银行卡交易",capability:"Separate recognized activity from an unauthorized item and request protection plus investigation",capabilityZh:"区分已确认活动与未授权项目，并请求保护和调查",specimen:"I recognize the café payment, but not the transfer made on Tuesday. Please freeze the card and open a dispute for that transfer.",move:"banking"},{unit:2,title:"Trace a missing delivery",titleZh:"追查显示已送达的包裹",capability:"Compare delivery evidence with the actual address and request a trace with a reference",capabilityZh:"比较配送证据与实际地址，并请求带编号的追查",specimen:"The photo shows a red door, but my entrance is blue. I’ve checked the lobby and neighbors; please open a trace and send the reference.",move:"delivery"},{unit:3,title:"Remove an unexpected recurring charge",titleZh:"取消意外的重复收费",capability:"Identify when a charge began, distinguish it from normal usage, and confirm cancellation and credit",capabilityZh:"确认收费起始时间、区分正常用量，并确认取消和退款",specimen:"The nine-pound protection charge first appears in March. I didn’t request it; please remove it from April and credit March.",move:"billing"}]},{stage:10,level:"Care & Responsibility Lab",title:"Close the loop when someone depends on you",titleZh:"当照护责任在你手中，完成信息闭环",thesis:"Confirm instructions, authorization, exceptions, and escalation when medicine, childcare, or an animal’s wellbeing depends on accurate handover.",thesisZh:"当用药、托管或动物健康依赖准确交接时，确认指令、授权、例外情况与升级条件。",units:[{unit:1,title:"Confirm medicine instructions",titleZh:"确认用药说明",capability:"Read back dose and timing, then ask about interactions and a missed dose",capabilityZh:"复述剂量和时间，再确认相互作用与漏服处理",specimen:"So that’s one tablet with breakfast and one with dinner. Should I avoid anything, and what should I do if I miss one?",move:"pharmacy"},{unit:2,title:"Hand over a pickup change",titleZh:"交接临时接送变更",capability:"Name the authorized adult, exact window, verification, and fallback",capabilityZh:"说明授权成人、准确时间窗、验证方式和备用方案",specimen:"For today only, my sister Leila will collect Sam between five and five fifteen. She’ll bring photo ID; call me if the plan changes.",move:"childcare"},{unit:3,title:"Describe a pet’s change",titleZh:"描述宠物状态变化",capability:"Compare normal baseline with observed change, timing, intake, and function without diagnosing",capabilityZh:"比较平时基线与观察变化、时间、进食饮水和功能，不自行诊断",specimen:"He normally finishes breakfast and wants a walk. Since yesterday morning, he has eaten half and stops after a few steps, though he is still drinking.",move:"veterinary"}]},{stage:11,level:"Shared Plans Lab",title:"Turn friendly intentions into shared plans",titleZh:"把友好意愿变成共同计划",thesis:"Coordinate food, time, and money without leaving ownership, exceptions, or the next confirmation implicit.",thesisZh:"协调食物、时间与费用时，不把负责人、例外情况或下一次确认留在暗处。",units:[{unit:1,title:"Make a shared dinner specific",titleZh:"把共同聚餐分工说具体",capability:"Assign each contribution with quantity, dietary coverage, and a confirmation date",capabilityZh:"为每项贡献明确负责人、数量、饮食需求与确认日期",specimen:"I’ll bring the main dish for six and make it dairy-free. Could Maya bring a salad and Rafi confirm dessert by Thursday?",move:"task ownership"},{unit:2,title:"Renegotiate an arrival time",titleZh:"明确改约与到达时间",capability:"Replace a vague delay with a new arrival, its impact, an alternative, and a confirmation point",capabilityZh:"用新到达时间、影响、替代方案与确认节点取代模糊的迟到通知",specimen:"The delayed train moves my arrival from seven to eight fifteen. Please start without me; I’ll confirm by five if that changes.",move:"plan repair"},{unit:3,title:"Split shared costs fairly",titleZh:"公平结算共同费用",capability:"Separate shared and optional items, expose the calculation, and request payment by a date",capabilityZh:"区分共同与可选项目、说明计算依据，并提出有日期的付款请求",specimen:"The accommodation is shared equally; the museum ticket was optional and only mine. Your share is forty-eight pounds; could you send it by Friday?",move:"expense settlement"}]},{stage:12,level:"Shared Space Lab",title:"Make temporary arrangements leave no residue",titleZh:"让临时安排不留下后续麻烦",thesis:"Protect shared space by recording condition, bounding permission, and closing the return loop when homes and belongings pass between people.",thesisZh:"当住所与物品在人之间交接时，通过记录状态、限定许可与完成归还闭环来保护共同空间。",units:[{unit:1,title:"Complete a move-in handover",titleZh:"完成搬家入住交接",capability:"Record keys, meter evidence, existing damage, and the date both sides will confirm the record",capabilityZh:"记录钥匙、表计证据、原有损伤，以及双方确认记录的日期",specimen:"I’ve received two keys and photographed the meter at 08:40. The scratch beside the bedroom window was already there; could we confirm the inventory by Tuesday?",move:"handover record"},{unit:2,title:"Agree an overnight guest plan",titleZh:"协商留宿安排",capability:"Bound who is staying, for how long, which shared-space routine applies, and when access ends",capabilityZh:"限定谁留宿、留宿多久、适用哪些共同空间规则，以及何时结束出入权限",specimen:"My cousin Noor would stay Saturday night only. We’ll be quiet after ten, use my bathroom supplies, and I’ll return the spare key on Sunday morning.",move:"bounded permission"},{unit:3,title:"Borrow and return an item",titleZh:"借用并完整归还物品",capability:"Confirm the item, accessories, starting condition, storage, return place, and date",capabilityZh:"确认物品、配件、初始状态、保管方式、归还地点与日期",specimen:"I’m borrowing the drill, two bits, and its case; the battery casing already has a small mark. I’ll keep everything dry and return it to your door tomorrow by six.",move:"return loop"}]},{stage:13,level:"Home Disruption Lab",title:"Keep a home disruption actionable",titleZh:"让家庭突发情况始终可处理",thesis:"In a leak, outage, or repair visit, separate observation from risk, take the safe action available now, and make ownership of the next update explicit.",thesisZh:"面对漏水、停电或维修入户时，区分观察与风险，采取当下可行的安全行动，并明确下一次更新由谁负责。",units:[{unit:1,title:"Escalate a water leak",titleZh:"升级处理漏水问题",capability:"Locate and evidence the leak, report containment and downstream impact, then request a timed response",capabilityZh:"定位并记录漏点，报告控制措施和下游影响，再请求有时限的响应",specimen:"Water is dripping from the joint beneath the kitchen sink. I’ve closed the local valve and checked that the ceiling downstairs is dry; please confirm an emergency plumber within thirty minutes.",move:"incident escalation"},{unit:2,title:"Prepare for a planned outage",titleZh:"为计划停电做好准备",capability:"Translate an outage window into owners for power, medicine, refrigeration, and a vulnerable-neighbor check",capabilityZh:"把停电时间窗转成设备供电、药品冷藏、冰箱管理和邻里确认的负责人",specimen:"Power is scheduled off from six to ten. I’ll charge the phones and lights; Maya will keep the medicine in the insulated pouch, and we’ll check on Mrs Chen at six fifteen.",move:"contingency planning"},{unit:3,title:"Bound repair access",titleZh:"限定维修入户权限",capability:"Verify the visitor, limit time and work area, protect private rooms, and close the temporary-key handover",capabilityZh:"核验来访者、限定时间与工作区域、保护私人房间，并完成临时钥匙交接闭环",specimen:"Please admit only the technician shown in the booking between two and three. Access is for the hall radiator only; keep the bedroom closed and return the temporary key to the envelope afterward.",move:"access control"}]},{stage:14,level:"Travel Handover Lab",title:"Keep the journey traceable",titleZh:"让旅途中的交接可以追踪",thesis:"When a room, rental, or bag changes hands, compare the confirmed record with reality, preserve condition evidence, and secure a remedy or next update you can verify.",thesisZh:"当房间、租赁物或行李发生交接时，对比确认记录与实际情况、保留状态证据，并取得可以核验的补救方案或下一次更新。",units:[{unit:1,title:"Resolve a room mismatch",titleZh:"处理酒店房型不符",capability:"Compare confirmed features with the assigned room, explain the practical impact, and negotiate bounded alternatives",capabilityZh:"对比确认配置与实际房间、说明实际影响，并协商有边界的替代方案",specimen:"The confirmation shows twin beds, a quiet room, and step-free access, but this key is for one bed upstairs. Could you move us now, or store our bags and confirm the correct room by three?",move:"booking recovery"},{unit:2,title:"Document a rental handover",titleZh:"记录租赁物品交接",capability:"Identify the rental, record existing condition and included equipment, then confirm return place and time",capabilityZh:"识别租赁物、记录原有状态和随附设备，再确认归还地点与时间",specimen:"This is bike twenty-four with the helmet and lock. I’ve photographed the existing scratch on the rear mudguard; I’ll return everything to Central Station by seven.",move:"rental condition"},{unit:3,title:"Trace delayed baggage",titleZh:"追踪延误行李",capability:"Make a bag distinguishable, anchor its last confirmed point, arrange delivery and essentials, and obtain a trace plus update time",capabilityZh:"让行李可辨认、锚定最后确认节点、安排投递与必需品，并取得追踪编号和更新时间",specimen:"It’s a deep-teal hard-shell case with an ochre ribbon and a scuff by one wheel. It was checked through in Madrid; please deliver it to this hotel and confirm the trace reference and next update time.",move:"baggage trace"}]},{stage:15,level:"Personal Service Lab",title:"Make personal service outcomes explicit",titleZh:"把个人服务的结果说清楚",thesis:"Before a cut, stitch, or repair becomes irreversible, anchor the request in a reference, protect what must not change, bound permission, and agree how the result will be checked.",thesisZh:"在剪裁、缝制或维修变得不可逆之前，用参考锚定需求、保护不可改变之处、限定授权范围，并约定如何验收结果。",units:[{unit:1,title:"Brief a haircut before the first cut",titleZh:"在第一剪之前说清理发需求",capability:"Translate a visual reference into measurable changes, protected features, and a preview point",capabilityZh:"把视觉参考转成可衡量改动、必须保留的特征与预览节点",specimen:"Please take about two centimeters off the ends, keep the layers below my chin, and leave the fringe long enough to tuck behind my ears. Could you show me the first section before continuing?",move:"hair consultation"},{unit:2,title:"Fit an alteration around real movement",titleZh:"围绕真实活动验收衣物修改",capability:"Specify the pinned target, construction to preserve, comfort requirement, and pre-stitch check",capabilityZh:"说明定位目标、保留工艺、舒适要求与缝制前检查",specimen:"Please shorten these trousers to the pinned line, keep the original cuff, and leave enough room to sit comfortably. Could we check the length with these shoes before you stitch?",move:"clothing alteration"},{unit:3,title:"Authorize a repair without surrendering privacy",titleZh:"授权维修但不放弃隐私边界",capability:"Describe a reproducible fault, authorize limited diagnostics, protect data, and set an approval threshold",capabilityZh:"描述可复现故障、授权有限诊断、保护数据并设定追加批准门槛",specimen:"The phone restarts when the battery reaches thirty percent. You may run hardware diagnostics, but please do not reset it or access personal files. Contact me before any repair over eighty pounds.",move:"device repair"}]},{stage:16,level:"Appointment & Pickup Lab",title:"Keep appointments and pickups traceable",titleZh:"让改约与取件始终可追踪",thesis:"When timing or condition changes at a service counter, preserve the relevant history, test the actual outcome, and leave with an explicit confirmation rather than an assumption.",thesisZh:"当服务时间或物品状态发生变化时，保留相关历史、检验实际结果，并取得明确确认，而不是依赖想当然。",units:[{unit:1,title:"Reschedule without hiding urgency",titleZh:"改约时不隐藏紧迫程度",capability:"Replace a slot while preserving symptom change, triage, cancellation options, and confirmation",capabilityZh:"更换时段时保留症状变化、分诊、候补方案与确认",specimen:"I need to move Tuesday at two. The pain now wakes me at night, though there is no swelling or fever. Is Thursday morning clinically appropriate, or should a clinician call me today? Please add me to the cancellation list and confirm the new slot.",move:"appointment repair"},{unit:2,title:"Test new glasses before accepting them",titleZh:"接收新眼镜前完成验收",capability:"Match the order, test distance and near vision separately, locate fit pressure, and agree the remedy",capabilityZh:"核对订单、分别测试远近视野、定位佩戴压力并约定补救",specimen:"These are the distance lenses from my order. The near card is clear, but street signs remain blurred through the right lens, and the frame presses behind my left ear. Could we verify the lens and adjust the fit before I accept them?",move:"pickup verification"},{unit:3,title:"Record a garment-care handover",titleZh:"记录衣物护理交接状态",capability:"Identify the garment, stain and existing damage, bound treatment permission, and confirm return condition",capabilityZh:"识别衣物、污渍与原有损伤，限定处理授权并确认返还状态",specimen:"This is a wool coat with a coffee mark on the left cuff, and this button is already loose. Please note both, contact me before using heat, and return it on a hanger by Friday.",move:"condition handover"}]},{stage:17,level:"Custom Order Lab",title:"Approve the order before production begins",titleZh:"在制作开始前确认定制订单",thesis:"A custom order becomes reliable when specifications, safety limits, substitution authority, proof, and handover are confirmed before materials and time become irreversible.",thesisZh:"在材料和时间投入变得不可逆之前，确认规格、安全限制、替代权限、样稿与交付，定制订单才真正可靠。",units:[{unit:1,title:"Read back a custom cake order",titleZh:"复述确认定制蛋糕订单",capability:"Separate serving and design requirements from allergy evidence, production limits, and pickup",capabilityZh:"区分份量与设计要求、过敏信息、制作限制和取件安排",specimen:"This is a six-serving vanilla cake with the ochre-and-teal design, for pickup Saturday at eleven. One guest has a severe nut allergy: can you describe your cross-contact controls before I decide whether this order is suitable?",move:"safety read-back"},{unit:2,title:"Bound a florist's substitutions",titleZh:"限定花店替代权限",capability:"Protect exclusions, palette, budget, delivery window, and approval before substitution",capabilityZh:"保护排除项、色板、预算、配送时间窗与替代前批准",specimen:"Please use cream, ochre, and deep-teal flowers with no lilies because the recipient has a cat. Keep the total under sixty pounds and call me before changing the palette; deliver between two and four, or leave it with the named neighbor.",move:"substitution boundary"},{unit:3,title:"Approve a print proof before the run",titleZh:"批量印刷前批准样张",capability:"Lock file version, dimensions, stock, proof checks, quantity, and authorization",capabilityZh:"锁定文件版本、尺寸、纸张、样张检查、数量与开印授权",specimen:"Please use the final-two file, trim it to A5 on matte stock, and print one physical proof first. I’ll check the margins and colors; do not run the remaining eighty copies until I approve that proof.",move:"production proof"}]},{stage:18,level:"Second-hand Exchange Lab",title:"Make second-hand exchanges verifiable",titleZh:"让二手交易可以核验",thesis:"Before money or custody changes hands, test what matters, expose condition and included items, make logistics executable, and preserve a receipt both sides can verify.",thesisZh:"在付款或保管权转移前，测试关键功能、公开状态与随附物品、让交接安排可执行，并保留双方都可核验的凭据。",units:[{unit:1,title:"Test a used appliance before deciding",titleZh:"决定前测试二手家电",capability:"Run a cold-start functional test, inspect condition, inventory accessories, and decide only after evidence",capabilityZh:"完成冷启动功能测试、检查状态、清点配件，并在取得证据后决定",specimen:"Before I decide, could we start the machine from cold, run water through the brew head, test the steam wand, and check underneath for leaks? Please confirm the portafilter and water tank are included, and note the existing scratch on the right side.",move:"condition test"},{unit:2,title:"Plan a bulky pickup before lifting",titleZh:"搬运前规划大件取件",capability:"Match dimensions to the route, assign disassembly and equipment, and confirm a bounded pickup window",capabilityZh:"让尺寸匹配搬运路线、分配拆卸与装备责任，并确认明确取件时间窗",specimen:"The bookcase is 180 by 80 by 30 centimeters. Could you confirm the shelves detach and the narrowest stair turn is wider than 82 centimeters? I’ll bring blankets and a van; please remove the shelves before pickup between ten and eleven.",move:"pickup logistics"},{unit:3,title:"Complete a public handover after inspection",titleZh:"验货后完成公共地点交接",capability:"Choose a public meeting point, inspect listed functions and accessories, then release payment and retain a receipt",capabilityZh:"选择公共交接地点、核验所列功能与配件，再付款并保留凭据",specimen:"Let’s meet at the station café at noon. I’ll test the shutter and autofocus, inspect the lens glass, and confirm the battery and charger. If those match the listing, I’ll pay through the marketplace and we’ll both keep the receipt.",move:"safe handover"}]},{stage:19,level:"Market & Checkout Lab",title:"Buy food for the moment you will use it",titleZh:"按实际使用时点购买食材",thesis:"A routine food shop becomes precise when ripeness is tied to use time, staffed-counter orders expose quantity and preparation, and checkout decisions depend on verifiable offer conditions.",thesisZh:"把成熟度连接到使用时间、把柜台订单的数量与处理方式说清、让结账决定取决于可核验的促销条件，日常买菜才真正精确。",units:[{unit:1,title:"Choose produce for two use dates",titleZh:"为两个使用日期挑选蔬果",capability:"Translate ripe or firm into use dates, inspect damage, and keep selections distinguishable",capabilityZh:"把成熟或偏硬连接到使用日期、检查损伤，并让不同选择保持可区分",specimen:"I need two avocados: one ripe enough for dinner tonight and one still firm for Sunday. Could you help me check for soft spots, and keep them in separate bags so I know which is which?",move:"ripeness timing"},{unit:2,title:"Make a staffed-counter order auditable",titleZh:"让人工柜台订单可以核对",capability:"Specify total, preparation, parcel split, safety question, and cold transport without assuming suitability",capabilityZh:"说明总量、处理方式、分装、安全询问与冷藏运输，不擅自假定适用",specimen:"Could I have four hundred grams of cooked chicken, thinly sliced and divided into two equal parcels? I have a sesame allergy; before I decide, could you tell me whether you can use clean utensils and a separate surface? Please wrap the parcels separately—I have a chilled bag.",move:"counter read-back"},{unit:3,title:"Verify a promotion before paying",titleZh:"付款前核验促销条件",capability:"Match shelf evidence to eligible items, expose the fallback, confirm the corrected total, and retain the receipt",capabilityZh:"让货架证据匹配符合条件的商品、说明备用决定、确认更正总额并保留小票",specimen:"The shelf card showed two of these jars for five pounds after the loyalty card is scanned. Could you check that these sizes qualify? If they do, I’ll take both after the total is corrected; if not, please remove the second jar. I’ll keep the receipt.",move:"checkout verification"}]},{stage:20,level:"Shared Facility Lab",title:"Keep shared facilities safe and traceable",titleZh:"让共享设施处理安全且可追踪",thesis:"When a shared machine, locker, or disposal point behaves unexpectedly, preserve the scene, protect other users and private information, and obtain an owned next step with a reference.",thesisZh:"当共享机器、快递柜或投放点出现异常时，应保护现场、其他使用者和私人信息，并取得有负责人、有编号的下一步。",units:[{unit:1,title:"Report a stopped laundromat cycle",titleZh:"报告自助洗衣程序中断",capability:"Identify the machine and cycle stage, preserve the locked condition, request safe recovery, and obtain a refund or service reference",capabilityZh:"识别机器与程序阶段、保持锁闭状态、请求安全取回衣物，并取得退款或维修编号",specimen:"The washer with the rust triangle stopped during the rinse about twelve minutes ago. The display is blank, water and my clothes are still inside, and I have not forced the door. Could you isolate the machine, open it safely, and confirm how the load and payment will be recovered with a service reference?",move:"safe fault report"},{unit:2,title:"Trace an empty parcel locker",titleZh:"追查空置的快递柜格口",capability:"Report the opening event without exposing the code, document only the empty compartment, leave other property untouched, and obtain a trace",capabilityZh:"在不暴露取件码的情况下报告开柜事件，只记录空格口、不触碰他人物品，并取得追踪编号",specimen:"My private collection code opened compartment twenty-four at 18:10, but it was empty. I photographed only the empty interior and intact hinge, then closed it without trying another door. Please open a trace, keep the code masked, and send the reference and next update time.",move:"privacy-preserving trace"},{unit:3,title:"Confirm sorting before unloading",titleZh:"卸物前确认回收分类",capability:"Inventory unusual materials, keep them separated and contained, confirm each accepted destination, and retain anything rejected",capabilityZh:"清点特殊材料、保持分隔与密封、确认每件物品的接收去向，并带走不接收物品",specimen:"I have household batteries with the terminals taped, an unplugged toaster, flattened cardboard, and a sealed partly full paint tin still in the car. Before I unload, could you confirm each collection point and whether you accept the paint? I’ll take back anything you cannot receive.",move:"controlled disposal"}]},{stage:21,level:"Recreation Planning Lab",title:"Make recreation safe and playable",titleZh:"让运动休闲安全且可执行",thesis:"A class, shared lane, or court booking works when ability and limits are disclosed without self-diagnosis, shared conventions are agreed before movement, and weather or access changes have a timed fallback.",thesisZh:"在不自行诊断的前提下说明能力与限制、运动开始前约定共享规则，并为天气或场地变化设置有时间节点的备用方案，课程、泳道或球场安排才真正可执行。",units:[{unit:1,title:"Join a first class with a modification plan",titleZh:"带着替代动作方案参加首次课程",capability:"Match the class to an honest baseline, name a movement limit, preview a modification, and confirm trial terms",capabilityZh:"让课程匹配真实基础、说明动作限制、预演替代动作并确认体验条款",specimen:"I’m new to group strength classes, though I can walk or cycle for thirty minutes. My right knee is uncomfortable with jumping and deep bends. Could you show me a low-impact alternative before Tuesday’s six o’clock class, place me near the instructor, and confirm the mat, band, and trial terms?",move:"bounded participation"},{unit:2,title:"Agree lane sharing before entering",titleZh:"下水前约定泳道共享规则",capability:"Match pace to a lane, confirm direction and spacing, and agree a pass-at-wall convention before swimming",capabilityZh:"让速度匹配泳道，并在游泳前确认方向、间距和池壁超越规则",specimen:"I usually swim one hundred meters in about two minutes. Is this the right lane? Before I enter, could we confirm clockwise circulation, a ten-second gap, and that a faster swimmer passes only at the wall after we acknowledge them?",move:"shared movement"},{unit:3,title:"Book a court with a weather fallback",titleZh:"预订带天气备用方案的球场",capability:"Lock court, window, lighting and equipment, then set a weather decision point, fallback, cancellation terms, and confirmation",capabilityZh:"锁定场地、时间窗、照明与装备，再设定天气判断节点、备用场地、取消条款和确认",specimen:"Please book the outdoor badminton court from five to six on Saturday, with lights, two rackets, and shuttlecocks. Let’s check rain by three: move us indoors if a court is available, otherwise cancel without charge, and send the final confirmation before we travel.",move:"weather contingency"}]},{stage:22,level:"Repair Handoff Lab",title:"Make repairs inspectable before they become irreversible",titleZh:"让维修在不可逆操作前可检查",thesis:"A repair handoff stays controlled when the observed fault, inspection boundary, authorization threshold, retained parts or data, and acceptance test are agreed before anything irreversible happens.",thesisZh:"在不可逆操作发生前约定可观察故障、检查边界、授权门槛、保留的零件或数据以及验收测试，维修交接才保持受控。",units:[{unit:1,title:"Inspect a bicycle before replacing parts",titleZh:"更换零件前先检查自行车",capability:"Describe the repeatable brake symptom, authorize inspection first, cap extra work, retain removed parts, and road-test before acceptance",capabilityZh:"描述可重复的刹车症状、先授权检查、限制额外工作、保留拆下零件并在验收前试骑",specimen:"The front brake rubs after rain, but the wheel turns freely when dry. Please inspect and call me with the cause and itemized estimate before replacing anything. Do not exceed sixty pounds without approval, keep any removed parts, and let me test the brake here before I accept the bicycle.",move:"bounded repair authorization"},{unit:2,title:"Protect privacy during a phone repair",titleZh:"手机维修期间保护隐私",capability:"Record the visible fault, remove credentials, restrict access and testing, authorize a priced repair only, and verify functions before unlocking personal data",capabilityZh:"记录可见故障、移除凭证、限制访问与测试、只授权有价格的维修，并在解锁个人数据前验证功能",specimen:"The screen is cracked, but touch and charging still work. I have backed it up and removed the SIM. Please keep the phone locked, use diagnostic mode rather than my apps, and call before any data reset or work above the quoted screen replacement. At collection, I’ll test touch, camera, charging, and the repair seal before signing in.",move:"privacy-bounded custody"},{unit:3,title:"Fit an alteration before final stitching",titleZh:"最终缝制前试穿改衣",capability:"Specify the worn-with context and reversible fitting, preserve allowance and offcuts, require a second fitting, and inspect symmetry before final acceptance",capabilityZh:"说明实际穿着情境与可逆试穿、保留余量和裁片、要求二次试穿，并在最终接收前检查对称",specimen:"I’ll wear these trousers with these shoes. Please pin both hems at the top of the shoe, baste them first, and keep the original allowance and any offcuts. I’d like a second fitting on Thursday before final stitching, then I’ll check both sides while standing and walking.",move:"reversible fitting"}]},{stage:23,level:"Payment Recovery Lab",title:"Keep everyday payments verifiable and recoverable",titleZh:"让日常支付可核验、可追回",thesis:"When cash, a transfer, or a terminal result is uncertain, stop repeated action, protect credentials, preserve the smallest useful evidence, verify through an independent channel, and leave with exactly one traceable next step.",thesisZh:"当现金、转账或终端结果不确定时，应停止重复操作、保护凭证、保留最小必要证据、通过独立渠道核验，并取得唯一且可追踪的下一步。",units:[{unit:1,title:"Report an ATM cash discrepancy",titleZh:"报告 ATM 出钞差异",capability:"State the requested and received cash without exposing credentials, preserve terminal and time evidence, avoid a second withdrawal, and obtain a dispute reference",capabilityZh:"在不暴露凭证的情况下说明请求与实收现金、保留终端和时间证据、避免再次取款，并取得争议编号",specimen:"I requested one hundred pounds at 18:42, but the machine dispensed sixty while my account shows the full debit. My card was returned, I did not make another withdrawal, and I kept the receipt. Please record the terminal location and time, open a cash-dispense dispute, and give me the reference and update date without asking for my PIN.",move:"credential-safe discrepancy"},{unit:2,title:"Verify a recipient before transferring",titleZh:"转账前核验收款人",capability:"Treat changed details as unverified, use a known contact channel, compare bounded recipient evidence, send a small test, and release the balance only after confirmation",capabilityZh:"把变更后的信息视为未核验，通过已知联系渠道、比对有限收款证据、先发小额测试，并在确认后才支付余款",specimen:"The invoice message contains new bank details, so I will not use them yet. I’ll call you on the number already in my contacts, confirm the account name and final four digits, send a one-pound test, and wait for you to confirm receipt before I send the remaining balance. I’ll keep both transfer receipts.",move:"independent payee verification"},{unit:3,title:"Resolve an uncertain card-terminal result",titleZh:"处理刷卡终端结果不明",capability:"Do not repeat a failed-looking tap, compare bank status with the merchant log, choose one next action, and retain a final receipt or incident reference",capabilityZh:"不重复看似失败的刷卡，通过银行状态与商户记录交叉核对、选择唯一下一步，并保留最终小票或事件编号",specimen:"The terminal lost connection after I tapped, so I will not tap again yet. My banking app shows the payment as pending. Could you check the terminal log for the same attempt? If it is recorded, please give me one receipt; if it is absent, void the uncertain attempt before we make one new payment. Either way, please give me the final receipt or incident reference.",move:"single-outcome reconciliation"}]},{stage:24,level:"Pet Care Continuity Lab",title:"Keep pet care observable and consistent",titleZh:"让宠物照护可观察、可连续执行",thesis:"Pet care becomes safer when observations are separated from diagnoses, routines are demonstrated and repeated back, exception and emergency thresholds are explicit, and shared-space introductions remain consensual and reversible.",thesisZh:"把观察与诊断分开、通过演示和复述交接日常流程、明确异常与紧急门槛，并让公共空间相遇保持双方同意且可随时退出，宠物照护才更安全。",units:[{unit:1,title:"Give a vet an observable timeline",titleZh:"向兽医提供可观察时间线",capability:"Report onset, count, intake, behavior and absence of key signs without naming a diagnosis, then ask what level of care is needed",capabilityZh:"在不自行诊断的情况下报告起始、次数、进食饮水、行为和关键未见症状，再询问所需照护等级",specimen:"Miso ate breakfast normally at seven, vomited twice between ten and eleven, drank water afterward, then hid and refused dinner. She has urinated, and I have not seen blood, breathing difficulty, collapse, or access to string or medicine. I brought a fresh sample. Could you tell me whether she needs examination now and what change should trigger emergency care?",move:"observable clinical timeline"},{unit:2,title:"Hand a pet routine to a sitter",titleZh:"把宠物日常流程交接给照护者",capability:"Define the normal baseline, demonstrate food, water, walks and prescribed routine, bound access, name exception thresholds, and complete a repeat-back",capabilityZh:"说明正常基线，演示喂食、饮水、散步与既定照护，限定进入范围、说明异常门槛，并完成复述演练",specimen:"Taro normally eats one measured cup at seven, has fresh water all day, and takes two twenty-minute leash walks. Please use only the labeled organizer exactly as prescribed; do not improvise a missed dose. Keep the study closed. If he refuses two meals, vomits twice, cannot settle, or has breathing trouble, call me and the listed clinic. Could you show me the routine once and send a check-in after each visit?",move:"closed-loop care handoff"},{unit:3,title:"Introduce dogs without forcing contact",titleZh:"不强迫接触地介绍犬只",capability:"Ask before approaching, keep both dogs leashed at neutral distance, parallel-walk, approach only with relaxed consent, and disengage at early stress signals",capabilityZh:"靠近前先询问、让两只狗牵绳并保持中立距离、平行行走，只在放松同意时靠近，并在早期压力信号出现时退出",specimen:"Is your dog comfortable meeting? Mine needs space at first. Let’s keep both dogs leashed, start about ten meters apart, and walk in the same direction. If both bodies stay loose, we can curve closer for a brief sniff; if either dog freezes, stares, tucks the tail, or pulls away, we’ll add distance and leave without forcing contact.",move:"consensual shared-space introduction"}]},{stage:25,level:"Roadside Evidence Lab",title:"Keep a road incident safe, factual, and closed",titleZh:"让道路事件安全、有据、可闭环",thesis:"Roadside English should first protect people from moving traffic, then locate the event and preserve observable facts, and finally close every vehicle handover with evidence rather than memory or blame.",thesisZh:"道路场景中的英语应先保护人员远离车流，再定位事件并保留可观察事实，最后用证据而不是记忆或归责完成车辆交接。",units:[{unit:1,title:"Call for roadside help from a safe position",titleZh:"在安全位置呼叫道路救援",capability:"State that everyone is safe, give road direction and a fixed landmark, describe the stopped vehicle and visible fault, name safety actions already taken, and agree an assistance update",capabilityZh:"说明人员安全，提供道路方向与固定地标，描述停车车辆和可见故障，说明已采取的安全措施，并约定救援更新",specimen:"We are both safely behind the barrier. Our teal hatchback is fully on the eastbound shoulder just after the river bridge, with its hazard lights on and a flat front-left tyre. We have not tried to change it beside traffic. Please confirm the recovery vehicle's description and text us an updated arrival time if the twenty-five-minute estimate changes.",move:"safe roadside location handoff"},{unit:2,title:"Record a minor collision without assigning fault",titleZh:"不预设责任地记录轻微碰撞",capability:"Check safety, prevent further danger, record time, place, positions and visible damage, exchange bounded details, note witnesses, and report without blame",capabilityZh:"确认安全、防止进一步危险，记录时间、地点、车位与可见损伤，交换必要信息、记录目击者，并在不归责的情况下报告",specimen:"Is everyone safe? Both cars are parked with the engines off and the lane is clear. At 14:20 in the north car park, our front bumpers touched at low speed. I will photograph the vehicle positions and visible marks, then exchange names, contact details, registration and insurer information. The trolley attendant saw the event. Let’s each report the observable facts without deciding fault here.",move:"non-attributive incident record"},{unit:3,title:"Close a rental-car return with evidence",titleZh:"用证据完成租车归还",capability:"Match fuel or charge and mileage to the agreement, photograph condition and contents, surface prior damage, transfer keys, and obtain a time-stamped return record",capabilityZh:"让油量或电量和里程符合协议，拍摄车况与车内物品，指出既有损伤，交接钥匙并取得带时间的归还记录",specimen:"The tank is full and the odometer reads 24,680. I have the fuel receipt from fifteen minutes ago and photos of all four sides, the empty cabin and boot. The small scratch on the rear-left door is already on the pickup report. Here are both keys. Please inspect the car with me and issue a time-stamped return receipt showing the fuel, mileage, keys and condition before I leave.",move:"evidenced vehicle return"}]},{stage:26,level:"Workday Continuity Lab",title:"Make work visible before responsibility moves",titleZh:"在责任转移前让工作状态可见",thesis:"A reliable workday handoff separates delay from coverage, completed work from pending work, and decisions from actions and open questions, so responsibility moves with a visible state and a confirmation point.",thesisZh:"可靠的工作日交接会区分延误与临时覆盖、已完成与待处理，以及决定、行动和未决问题，让责任随可见状态和确认节点一起转移。",units:[{unit:1,title:"Repair a late arrival with explicit coverage",titleZh:"用明确代班修复迟到影响",capability:"Replace a vague delay with cause-neutral evidence, a revised arrival, the immediate impact, a named temporary owner, a bounded task, and a hand-back update",capabilityZh:"用中立的延误事实、新到达时间、即时影响、具名临时负责人、限定任务和交还更新替代模糊迟到通知",specimen:"My train is being held outside Central, so I now expect to arrive at 09:25 rather than 08:50. That affects the 09:00 reception opening. Rafi has agreed to unlock the desk and use the shared opening checklist, but not approve refunds. I will update both of you by 09:10 and take the desk back when I arrive; please confirm that coverage works.",move:"delay-to-coverage repair"},{unit:2,title:"Hand over unfinished work at shift change",titleZh:"换班时交接未完成工作",capability:"Separate what is complete, waiting and unsafe to continue, then assign each next action, owner, deadline, exception and check-back",capabilityZh:"区分已完成、等待中和不可继续的事项，再为每项明确下一步、负责人、期限、例外和回查节点",specimen:"The six boxed orders are collected. Order C is packed but waiting for the allergy-control answer, so do not release it; Maya will call the customer by four after the manager confirms. We have two oat-milk cartons left, and Rafi has added tomorrow's order. The grinder is unplugged and tagged after overheating; use the second grinder and check the repair log at five. Could you read back those three statuses and owners?",move:"state-owner-exception handoff"},{unit:3,title:"Close a meeting with decisions and owners",titleZh:"用决定与负责人结束会议",capability:"Read back settled decisions, convert actions into one owner and due point, preserve open questions with an evidence source, and schedule the next review",capabilityZh:"复述已定决定，把行动落实为单一负责人和期限，保留带证据来源的未决问题，并安排下一次复核",specimen:"Before we finish: we decided to test the teal cover only. Maya owns the ten-user test and will share results by Thursday at three. Rafi will request the revised supplier quote by Wednesday noon. The fabric durability is still open; Lena will check the lab report, not guess from the sample. We will review that evidence Friday at ten. Could each owner confirm their action and deadline?",move:"decision-action-open-question close"}]},{stage:27,level:"Parcel Custody Lab",title:"Make every parcel handoff traceable",titleZh:"让包裹的每次交接都可追踪",thesis:"A parcel remains recoverable when contents and condition are evidenced before custody changes, every exception is recorded without premature blame, and return tracking is connected to a specific refund checkpoint.",thesisZh:"在保管责任变化前记录内容与状态、对异常进行无预设归责的记录，并把退货追踪连接到明确退款节点，包裹问题才可恢复。",units:[{unit:1,title:"Dispatch a fragile parcel with a complete record",titleZh:"用完整记录寄出易碎包裹",capability:"Evidence the intact item, describe contents truthfully, confirm protective packing, weight, destination, service, declared value, delivery aim and first carrier scan",capabilityZh:"记录物品完好状态，如实说明内容，确认防护包装、重量、目的地、服务、申报价值、预计送达与承运方首次扫描",specimen:"This parcel contains one ceramic mug, photographed intact before packing. It is in a fitted inner box inside this cushioned outer carton. Please confirm the final weight, the tracked service to Dublin, the sixty-pound declared value and Friday delivery aim. I will keep the acceptance receipt only after the first carrier scan matches this parcel.",move:"pre-custody dispatch record"},{unit:2,title:"Document delivery damage before discarding evidence",titleZh:"丢弃证据前记录配送损坏",capability:"Record the sealed exterior and handoff condition, open carefully, preserve packaging, match item damage to the order, and obtain a case reference and evidence instructions without assigning cause",capabilityZh:"记录封箱外观与交付状态，谨慎开箱、保留包装，让物品损坏对应订单，并在不判断原因的情况下取得案件编号与证据说明",specimen:"The sealed parcel arrived at 16:10 with a crushed top-left corner and a damp patch underneath. I photographed all six sides before moving it, and the courier recorded the condition. On opening, the lamp shade is split but the base and cable remain inside. I have kept the carton, inner wrap and label. Please open a damage case, tell me which evidence to upload, and give me the reference and next update date without deciding the cause yet.",move:"non-attributive damage record"},{unit:3,title:"Connect a return scan to the refund checkpoint",titleZh:"把退货扫描连接到退款节点",capability:"Match the item and return window, evidence condition and contents, remove stale routing, obtain the first scan, retain the receipt, and define merchant receipt, inspection and refund updates",capabilityZh:"核对商品与退货期限，记录状态和内容，移除旧路由信息，取得首次扫描、保留收据，并明确商家收件、检查和退款更新",specimen:"These unworn ochre shoes match order 418 and the return is due Monday. I photographed both soles, the laces and dust bag, replaced the shoe box inside a separate sealed carton, and covered the old routing label. Please scan it while I am here and give me the receipt. I will track merchant delivery, then request an inspection update within two working days and the refund reference if no decision appears.",move:"scan-to-refund return loop"}]},{stage:28,level:"Public Transit Continuity Lab",title:"Keep a public-transport journey recoverable",titleZh:"让公共交通行程始终可恢复",thesis:"A reliable transit journey verifies fare and access before entry, turns disruption into one chosen route with a timed update, and reports lost property with enough evidence to trace it without exposing private information.",thesisZh:"可靠的公共交通行程会在进站前核验票种与通行条件，把中断转成一条已选择且有更新时间的路线，并用足够但不过度暴露隐私的证据追踪遗失物。",units:[{unit:1,title:"Verify fare and step-free access before entering",titleZh:"进站前核验票种与无障碍通行",capability:"Match the ticket to time and zones, verify every lift and transfer, name the staffed assistance point, and define what happens if access changes",capabilityZh:"让票种匹配时间与区域，核验每部电梯和换乘，说明有人值守的协助点，并定义通行条件变化后的处理",specimen:"We need an off-peak day ticket covering zones one to three. Before we enter, please confirm that both lifts on the step-free route are operating, allow twelve minutes for the interchange, and arrange assistance at the blue information point by 09:20. If either lift fails, please tell us before validation and offer a step-free alternative or refund the unused tickets.",move:"pre-entry fare and access verification"},{unit:2,title:"Rebuild a journey after a service suspension",titleZh:"线路停运后重建行程",capability:"Confirm the affected segment, compare arrival and accessibility consequences, choose one valid alternative, communicate the new arrival, and set the next checkpoint",capabilityZh:"确认受影响区段、比较到达与无障碍影响、选择一条票务有效的替代路线、通知新到达时间，并设置下一检查点",specimen:"The Green line is suspended between Market and River, so we cannot make the 10:15 arrival. Please confirm that our tickets are valid on the replacement bus from bay six and that it is step-free. We will take the 09:40 bus, expect to arrive at 10:35, tell our host once, and check the live service again at Harbor before the final connection.",move:"single-route disruption recovery"},{unit:3,title:"Trace lost property without oversharing",titleZh:"不过度泄露隐私地追踪遗失物",capability:"Distinguish the item, reconstruct the bounded journey and seat area, disclose only safe contents, protect sensitive identifiers, and obtain a case reference plus update time",capabilityZh:"让物品可区分、重建有限的行程与座位区域，只披露安全内容、保护敏感标识，并取得案件编号和更新时间",specimen:"I left a deep-teal tote with an ochre stitched patch on the eastbound numberless city bus at about 17:25, probably beside the rear-facing seats. I boarded near the library and left at Cedar Park. It contains a grey water bottle and a folded raincoat; I will describe any private item only through the secure verification step. Please open a lost-property trace, give me the reference, and confirm when I should check again tomorrow.",move:"privacy-bounded lost-property trace"}]},{stage:29,level:"Digital Account Continuity Lab",title:"Keep digital access secure and reversible",titleZh:"让数字访问保持安全且可恢复",thesis:"Digital service English should separate a message from trusted evidence, close subscriptions before renewal with portable data and durable proof, and restore accounts without disclosing secrets while revoking every unknown session.",thesisZh:"数字服务英语应把消息与可信证据分开，在续费前完成订阅关闭、数据导出和凭据留存，并在不披露秘密的情况下恢复账户、撤销所有陌生会话。",units:[{unit:1,title:"Verify a suspicious sign-in alert independently",titleZh:"通过独立入口核验可疑登录通知",capability:"Do not use the alert link, enter through a known route, compare bounded sign-in evidence, classify the event, protect the account if unknown, and retain the security record",capabilityZh:"不使用通知内链接，通过已知入口进入，比对有限的登录证据、判断事件，如不认识则保护账户，并保留安全记录",specimen:"I will not use the link in this alert. I opened the service from my saved bookmark and found a sign-in at 22:14 from a Windows device near Leeds. I do not recognize it. Please sign out that session, let me change the password through this official page, require a fresh sign-in on other devices, and give me the security-event reference. I will not share my password or one-time code.",move:"independent alert verification"},{unit:2,title:"Close a subscription before renewal",titleZh:"在续费前完成订阅关闭",capability:"Confirm the plan and renewal cutoff, export owned data, cancel without deleting evidence, distinguish access end from billing end, and retain a dated confirmation",capabilityZh:"确认方案与续费截止时间、导出自有数据、取消但不删除证据、区分访问结束与计费结束，并保留带日期确认",specimen:"This trial changes to the monthly plan at 23:59 on Friday. I have exported my three project folders. Please cancel renewal now without deleting the account, confirm that no charge will be attempted, keep read-only access until Sunday, and send a dated cancellation reference showing the plan, cutoff and access end. I will verify the next statement rather than rely on the button alone.",move:"cutoff-to-confirmation subscription close"},{unit:3,title:"Recover an account without surrendering secrets",titleZh:"不交出秘密地恢复账户",capability:"Use the official recovery route and bounded identity check, refuse password or code disclosure, restore access, revoke unknown sessions, replace recovery channels, and store fresh recovery codes offline",capabilityZh:"使用官方恢复入口与有限身份核验，拒绝披露密码或验证码，恢复访问、撤销陌生会话、更换恢复渠道，并离线保存新的恢复码",specimen:"I started recovery from the official help page on my trusted laptop. I can complete the in-product identity check, but I will not send a password, one-time code or full security answer. Once access is restored, please help me revoke every other session, remove the unfamiliar recovery address, add my verified phone ending 42, issue fresh recovery codes, and confirm the old codes no longer work. I will store the new codes offline.",move:"secret-safe account recovery"}]},{stage:30,level:"School & Childcare Continuity Lab",title:"Keep every child handoff explicit and closed",titleZh:"让每次儿童照护交接都明确闭环",thesis:"A safe school or childcare handoff separates one-time authorization from standing access, reports absence through observations rather than diagnosis, and turns an evening routine into a demonstrated, repeated-back plan with clear contact thresholds.",thesisZh:"安全的学校或照护交接会区分一次性授权与长期权限，用观察而不是诊断报告缺勤，并把晚间流程转成经过演示、复述且联系门槛清晰的计划。",units:[{unit:1,title:"Authorize a one-day pickup change",titleZh:"授权一次性的接送人变更",capability:"Name the child, class, substitute collector, date, time and gate, keep identity and passphrase checks private, preserve standing contacts, and obtain school confirmation",capabilityZh:"说明儿童、班级、代接人、日期、时间和校门，私密完成身份与口令核验，保留长期联系人，并取得学校确认",specimen:"For today only, Rafi Chen will collect Leo from Maple class at 15:30 at the north gate instead of Maya. Rafi will bring photo ID, and I submitted his full details through the secure parent portal. Please verify the family passphrase privately rather than repeating it aloud. This does not change our standing collectors; please send confirmation that reception and the gate team have the same instruction.",move:"bounded pickup authorization"},{unit:2,title:"Reconnect learning after an absence",titleZh:"缺勤后重新连接学习安排",capability:"Give an observable absence timeline, ask the school to apply its return policy, inventory missed learning, agree a bounded first-day adjustment, and set a teacher check-in",capabilityZh:"提供可观察的缺勤时间线，请学校适用其返校规则，清点缺失学习内容，约定首日有限调整，并设置教师确认",specimen:"Sam was absent Monday and Tuesday with a fever and low energy. There has been no fever since Tuesday morning without fever-reducing medicine; Sam is eating, drinking and much more active. Could you confirm whether Thursday meets the school's return policy? Please send the maths sheet and reading chapter, excuse strenuous PE on the first day, and ask the teacher to check in before lunch. We will update you if the condition changes.",move:"observation-to-return learning bridge"},{unit:3,title:"Hand an evening routine to a sitter",titleZh:"向照护者交接晚间流程",capability:"Demonstrate food and allergy boundaries, homework and bedtime, secure the home, distinguish delay from urgent danger, identify trusted contacts, and complete a repeat-back",capabilityZh:"演示食物与过敏边界、作业和就寝流程，确保住所安全，区分延迟与紧急危险，说明可信联系人，并完成复述",specimen:"Dinner is the sealed teal meal box at six; do not substitute food because the allergy card applies. Homework is in the blue folder, lights out is at eight-thirty, and the balcony stays locked. If we are fifteen minutes late, call Maya, then Rafi; stay here with Noor. For immediate danger, ensure safety, call local emergency services first, then contact us. Could you show me the meal label, balcony lock and contact order, then read the routine back?",move:"demonstrated childcare handoff"}]},{stage:31,level:"Utility Account Continuity Lab",title:"Keep household utility responsibility traceable",titleZh:"让家庭水电账户责任始终可追踪",thesis:"A utility account remains recoverable when opening evidence fixes the starting state, outage reports separate safe observations from guesses, and move-out closure connects the final reading to billing, payment and a durable reference.",thesisZh:"通过开户证据固定起始状态、用安全观察而非猜测报告异常，并在搬离时把最终读数连接到账单、付款与持久编号，家庭水电账户才可恢复、可追踪。",units:[{unit:1,title:"Open service from an evidenced meter reading",titleZh:"用有证据的表计读数开通服务",capability:"Match the exact premises and start date, record the meter serial, reading, time and photo, name the account holder, confirm tariff and payment terms, and retain an opening reference",capabilityZh:"核对准确地址与开始日期，记录表计序列号、读数、时间和照片，明确账户持有人，确认费率与付款条件，并保留开户编号",specimen:"Please open electricity service for flat 3B from 2 September. At 09:10 today, meter serial ending 284 showed 01876; I photographed the serial and reading together before using power. The account holder is Maya Chen. Please confirm the standard variable tariff, monthly direct-debit amount and first review date, then send an opening reference that links this start date and reading.",move:"evidenced utility opening"},{unit:2,title:"Report an unexpected utility outage safely",titleZh:"安全报告突发水电中断",capability:"State the affected service and start time, distinguish home, building and area scope through safe observations, avoid damaged equipment and repeated resets, report essential impact, and obtain an incident reference plus next update",capabilityZh:"说明受影响服务与开始时间，通过安全观察区分住户、楼宇与区域范围，不接触受损设备或反复复位，说明必要影响，并取得事件编号与下次更新时间",specimen:"Our electricity went off at 18:40. Our flat and the shared corridor are dark, while the next building still has lights. The breaker appears on; we have not reset it repeatedly or touched the warm, damaged socket. The fridge and one phone charger are affected. Please log the outage, give us the incident reference, and update the restoration estimate by 20:00.",move:"safe bounded outage report"},{unit:3,title:"Close a utility account at move-out",titleZh:"搬离时闭环水电账户",capability:"Fix the final service date, record meter identity, reading, time and photo, connect key custody and forwarding details, define final bill and credit handling, stop automatic payment after settlement, and retain a closing reference",capabilityZh:"确定最终服务日期，记录表计身份、读数、时间和照片，连接钥匙交接与转寄信息，明确最终账单和余额处理，在结清后停止自动付款，并保留关闭编号",specimen:"Please close the gas account after 16:00 on 30 September. At 15:45, meter serial ending 611 showed 00492, and I photographed the serial and reading before handing both keys to the agent. Send the final bill to my verified online account, return any credit to the existing payment method, and stop direct debit only after the balance settles. Please issue a closing reference with the date, reading and billing status.",move:"reading-to-settlement account close"}]},{stage:32,level:"Shared-Building Continuity Lab",title:"Make shared-space agreements executable",titleZh:"让共享空间约定真正可执行",thesis:"Shared-building English works when access is bounded by a visible slot and release state, recurring disturbance is described through observable patterns and a review point, and bulky-item custody moves only through an authorized route and collection record.",thesisZh:"共享住宅英语只有在使用权由可见时段与释放状态限定、持续干扰通过可观察规律与复核节点描述、大件物品只沿授权路线与收运记录转移时，才真正可执行。",units:[{unit:1,title:"Reserve and release a shared laundry slot",titleZh:"预约并释放共享洗衣时段",capability:"Name the room, machine, start and end, confirm access and occupancy rules, bound the load and cycle, clean the shared area, release the machine, and define a fault fallback",capabilityZh:"说明房间、机器与起止时间，确认门禁和占用规则，限定衣物与程序，清理共享区域、释放设备，并定义故障备用流程",specimen:"Please reserve washer two in the ground-floor laundry from 18:30 to 19:15 today. I will use one labelled basket and the forty-minute cotton cycle, collect it before the slot ends, wipe the seal and leave the door ajar. Please confirm my fob access and booking reference. If the washer is marked out of service, I will not move another resident's load; message me with the next available machine.",move:"slot-to-release shared use"},{unit:2,title:"Resolve recurring noise through a reviewable agreement",titleZh:"用可复核约定处理持续噪音",capability:"Describe dates, times, duration and effect without guessing intent, make a direct bounded request, propose a short trial, confirm quiet-hour expectations, and set a neutral follow-up or escalation point",capabilityZh:"在不猜测动机的情况下说明日期、时间、持续时长与影响，提出直接且有限的请求，约定短期试行、确认安静时段，并设置中立复核或升级节点",specimen:"Could we discuss the music after 23:00? On Monday, Wednesday and last night it was audible in our bedroom for about forty minutes and woke us twice. I am not assuming why; could you keep speakers off the shared wall and lower the bass during the building's 22:00–07:00 quiet hours for the next seven nights? Let’s check in next Friday. If it continues, we can ask the manager to review the same dated log with both of us.",move:"observation-to-review neighbor agreement"},{unit:3,title:"Arrange a bulky-item collection without blocking access",titleZh:"在不阻塞通道的情况下安排大件收运",capability:"Identify and measure the item, verify accepted contents and preparation, book the authorized date and set-out window, protect the lift route and exit, place it only in the designated bay, and retain collection evidence",capabilityZh:"识别并测量物品，核验可收内容与准备要求，预约授权日期和放置时段，保护电梯路线与出口，只放入指定区域，并保留收运证据",specimen:"The item is one dismantled wooden bookcase: four panels, each under 180 by 40 centimetres, with screws bagged separately. Please confirm it is accepted for Tuesday collection and book reference BULK-41. We will protect the lift, move it between 19:00 and 20:00, keep the fire exit clear, and place it only inside bay C after the set-out time. Please confirm collection by noon Wednesday or tell us when to bring it back inside.",move:"authorized bulky-item custody"}]},{stage:33,level:"Public Library Continuity Lab",title:"Keep every library loan attributable",titleZh:"让每次图书馆借阅都可归属",thesis:"Library access stays useful when membership proves eligibility without unnecessary disclosure, collection fixes the exact edition and starting condition before custody changes, and a disputed return preserves evidence while the library traces every possible location.",thesisZh:"办理借阅资格时不过度披露、取书时在保管责任变化前固定准确版本和起始状态、归还争议时保留证据并让图书馆追查所有可能位置，公共图书馆服务才持续可靠。",units:[{unit:1,title:"Join a library without oversharing",titleZh:"不过度披露地办理图书馆借阅证",capability:"Ask which eligibility evidence is required, present it privately without unnecessary copies, confirm the member name and contact channel, understand loan, due-date and renewal rules, define lost-card action, and retain membership confirmation",capabilityZh:"询问所需资格证据，私密出示且不留下不必要副本，确认会员姓名与联系渠道，理解借阅、到期与续借规则，明确遗失卡处理，并保留办证确认",specimen:"I live in the service area and would like to join. Which one identity document and address proof do you need to inspect? Please view them at the desk and return them without keeping extra copies unless required. Register me as Maya Chen and send due-date notices to my verified email. Could you confirm the six-item limit, three-week loan, renewal conditions and how to freeze a lost card, then give me the membership confirmation?",move:"privacy-bounded library membership"},{unit:2,title:"Collect a hold with the loan state confirmed",titleZh:"确认借阅状态后领取预约图书",capability:"Match member, title, author, edition and hold deadline, record existing damage before checkout, verify accessories, confirm due date and renewal eligibility, close the hold, and retain the loan receipt",capabilityZh:"核对会员、书名、作者、版本与预约截止时间，在借出前记录既有损伤，核验附件，确认到期日与续借资格，关闭预约并保留借阅凭据",specimen:"I am collecting the hold for Maya Chen: the deep-teal 2024 second edition of City Trees by A. Noor, held until 18:00 today. Before checkout, please note the two-centimetre tear at the top of the dust jacket; the map insert is present and undamaged. Please confirm the 24 October due date, whether another reader's request would block renewal, close the hold, and issue a receipt with this copy and condition.",move:"hold-to-loan custody"},{unit:3,title:"Trace a return that still appears on the account",titleZh:"追查仍显示在账户中的已归还图书",capability:"Identify the exact item, return point and time, preserve bounded evidence, request checks of the slot, transit bins, shelves and scan history, pause charges during the trace, and obtain a case reference plus update",capabilityZh:"识别准确物品、归还点与时间，保留有限证据，请求检查归还口、转运箱、书架与扫描记录，在追查期间暂停收费，并取得案件编号与更新时间",specimen:"My account still shows The Quiet River, copy ending 62, although I returned it through the east after-hours slot at 19:35 on Tuesday. My photo shows the slot's accepted indicator, and I kept the time-stamped return receipt. Please check that slot, the overnight transit bins, reshelving carts, the shelf and scan history without marking the item lost yet. Pause any charge during the trace, give me case LIB-48, and update me by Friday at noon.",move:"evidenced return trace"}]},{stage:34,level:"Ticketed Event Continuity Lab",title:"Keep the event promise valid from sale to remedy",titleZh:"让活动承诺从购票到补救始终有效",thesis:"A ticketed event remains recoverable when the performance, seats, access and full price are fixed before payment, failed entry is restored through the official booking without exposing reusable credentials, and cancellation ends in one explicit replacement or refund with durable proof.",thesisZh:"在付款前固定场次、座位、通行与总价，通过官方订单恢复失效入场而不暴露可复用凭证，并让取消最终落到一个明确的改期或退款及持久凭据，票务活动才可恢复。",units:[{unit:1,title:"Buy seats only after access and price are fixed",titleZh:"确认通行与总价后再购买座位",capability:"Match the event, venue, date and time, select adjacent seats with a verified sightline, confirm the full step-free route and hearing support, expose all fees and the exchange cutoff, then retain the purchase confirmation",capabilityZh:"核对活动、场馆、日期与时间，选择视线已核验的相邻座位，确认完整无障碍路线与助听支持，显示所有费用和改签截止时间，并保留购票确认",specimen:"Before payment, please confirm two adjacent seats C12 and C13 for the 19:30 Friday performance at River Hall. The sightline must be unobstructed, with a step-free route from the street through the lift to row C, and the hearing loop active in that section. Please show the full total including fees, the Thursday 17:00 exchange cutoff, and issue one confirmation naming the performance, seats and access arrangements.",move:"pre-payment event verification"},{unit:2,title:"Recover entry when a mobile ticket fails",titleZh:"手机票失效时恢复入场",capability:"Keep the queue clear, use the staffed official route, identify the purchase with bounded evidence, never disclose a reusable code, verify ticket status, void duplicates, issue exactly one replacement credential, and confirm admission",capabilityZh:"保持队伍畅通，使用有人值守的官方路径，以有限证据识别订单，绝不披露可复用代码，核验票务状态、作废重复凭证、只签发一个替代凭证，并确认入场",specimen:"One of our two mobile tickets will not load, so we have stepped out of the entry line. The booking is for Maya Chen, tonight at 19:30, seats C12 and C13; I can show the masked purchase receipt and photo ID at the official help desk, but I will not send or read out any ticket code. Please verify both tickets, void any duplicate token, issue one replacement for the failed ticket, and confirm both seats have entered under case ENTRY-54.",move:"official ticket-entry recovery"},{unit:3,title:"Choose one remedy after an event cancellation",titleZh:"活动取消后选择一个明确补救",capability:"Confirm cancellation and affected tickets, compare a rescheduled date, seats, access and price with the full refund amount, choose one remedy, close the other path, preserve the original payment route, and obtain a dated settlement reference",capabilityZh:"确认取消与受影响票券，对比改期日期、座位、通行和价格与全额退款金额，选择一个补救并关闭另一条路径，保留原付款路径，并取得带日期结算编号",specimen:"Please confirm that Saturday's 20:00 performance was cancelled and both tickets A18 and A19 are affected. The offered Thursday date keeps the seats and step-free access with no extra fee, but we cannot attend. We choose a full refund of £84 to the original card, not vouchers or rescheduling. Please close both tickets, confirm the five-working-day refund window, and issue dated case CANCEL-72 showing the amount and payment route.",move:"single-path cancellation remedy"}]},{stage:35,level:"Grocery Delivery Continuity Lab",title:"Keep every grocery decision item-specific",titleZh:"让每项买菜决定都精确到单品",thesis:"A grocery delivery remains usable when substitution authority is assigned item by item before payment, temperature-sensitive custody is checked before food is mixed or stored, and missing or wrong goods are remedied without discarding the valid remainder of the order.",thesisZh:"付款前逐项分配替代权限、在食品混放或储存前核验温度敏感的保管状态，并对缺件错件逐项补救而不否定订单中正确部分，线上买菜结果才真正可用。",units:[{unit:1,title:"Set item-by-item substitution boundaries",titleZh:"逐项设置替代品边界",capability:"Identify quantity and essential attributes for each item, allow a bounded equivalent with a price ceiling, prohibit substitution where safety or purpose requires, define a flexible category by weight, confirm delivery and handoff limits, and retain the authorized summary",capabilityZh:"为每件商品说明数量与关键属性，允许有价格上限的等价替代，在安全或用途需要时禁止替代，按重量定义灵活类别，确认配送与交接边界，并保留授权摘要",specimen:"For two one-litre cartons of plain oat drink, you may substitute the same size and unsweetened type up to £2.20 each. Do not substitute the sesame-free stir-fry sauce because the allergy requirement is item-specific; refund it if unavailable. For lentils, either green or brown is acceptable if the total remains 500 grams. Deliver between 18:00 and 19:00 and hand the chilled bags to us—do not leave them outside. Please show these rules in the final order summary before payment.",move:"item-specific substitution authority"},{unit:2,title:"Verify a grocery delivery before storage",titleZh:"储存前核验买菜配送",capability:"Match arrival time, bag count and order, inspect seals and separated temperature zones, preserve evidence of an exception, keep affected food apart without declaring it safe, record the courier handoff, and store unaffected goods promptly",capabilityZh:"核对到达时间、袋数与订单，检查封条和分隔温区，保留异常证据，把受影响食品单独放置而不自行宣布安全，记录配送交接，并及时储存未受影响商品",specimen:"The delivery arrived at 18:24 with six bags matching the handoff list: three ambient, two chilled and one frozen. The ambient seals are intact and the frozen vegetables are still solid, but one chilled seal is torn and its indicator is outside the accepted range. I photographed that bag before opening and will keep its milk and yogurt separate rather than decide they are safe. Please record the exception and bag number; we will refrigerate the intact chilled bag and store the frozen and ambient items now.",move:"pre-storage grocery custody check"},{unit:3,title:"Resolve missing and wrong items proportionately",titleZh:"按比例处理缺件与错件",capability:"Match the order and delivered bags, preserve correct goods, identify each missing or wrong item and unsuitable substitution, refuse only the affected item, request exact item-level credits to the original payment route, and retain a case plus settlement time",capabilityZh:"核对订单与已交付袋数，保留正确商品，识别每个缺失或错误商品及不合适替代，只拒绝受影响商品，请求准确的单品退款至原付款路径，并保留案件编号与结算时间",specimen:"Order 418 lists four bags and all four arrived. The produce, bread and five other items are correct, so we are keeping them. The four-pack of plain yogurt costing £3.60 is missing, and the delivered sweetened oat drink is not the authorized unsweetened substitute, so we will not keep that £2 item. Please refund those two item amounts, £5.60 total, to the original card without cancelling the valid order, and send case FOOD-63 with the three-working-day settlement time.",move:"item-level grocery remedy"}]},{stage:36,level:"Pharmacy Pickup Continuity Lab",title:"Keep a pharmacy pickup private, exact and recoverable",titleZh:"让药房取药保持私密、准确且可恢复",thesis:"A pharmacy pickup remains reliable when identity and collection authority are verified privately, the sealed package and pharmacist-provided directions are checked before handoff, and an unavailable item moves only through an authorized prescriber-pharmacist path rather than an improvised substitution.",thesisZh:"私密核验身份与代领权限、交接前核对密封包装及药师提供的说明，并让缺货项目只通过处方方与药师的授权路径处理而非临时替换，药房取药才持续可靠。",units:[{unit:1,title:"Confirm a prescription is ready without oversharing",titleZh:"不过度披露地确认处方可取",capability:"Use the pharmacy's private channel, give only the identifiers requested for matching, confirm which items are ready or still pending without naming them in public, distinguish personal pickup from authorized collection, ask what evidence is required, and retain a collection reference and window",capabilityZh:"使用药房的私密渠道，只提供匹配所需的身份信息，在公共场合不说出药品名称地确认哪些项目可取或仍待处理，区分本人取药与授权代领，询问所需凭证，并保留取药编号与时间窗",specimen:"Could we continue at the private counter? I am Maya Chen and I received collection reference RX-41; I can show the requested photo ID here, but I will not call out my address or the item names in the queue. Please confirm how many sealed items are ready, whether any remain pending, and the collection window. Rafi is not collecting for me today; if that changes, please explain the pharmacy's authorized-collector evidence rather than adding him now.",move:"privacy-bounded readiness check"},{unit:2,title:"Verify the sealed package before accepting it",titleZh:"接收前核验密封包装",capability:"Move to the consultation point, match the intended person and item count, inspect seal and label details without opening the package, ask the pharmacist to explain unclear directions and storage or transport requirements, repeat the instructions back for confirmation, and retain the receipt and contact route",capabilityZh:"移至咨询位置，核对使用者与项目数量，不拆封检查封条和标签信息，请药师解释不清楚的说明及储存或运输要求，复述说明以确认，并保留收据与联系渠道",specimen:"Before I accept these two sealed items, could we check them at the consultation counter? The name is Maya Chen and the item count is two; both seals are intact. Please compare the label details with the pharmacy record, explain the printed directions and the storage and journey-home requirements, and correct me if my read-back is wrong. I will not open or use either item until the pharmacist resolves anything unclear. Please include the pharmacy contact route on the receipt.",move:"pharmacist-led sealed handoff"},{unit:3,title:"Resolve an unavailable item through the authorized path",titleZh:"通过授权路径处理缺货项目",capability:"Separate available from unavailable prescription items, preserve the ready items, ask the pharmacist whether a partial collection is permitted, avoid requesting or accepting an unapproved substitute, authorize contact with the prescriber or a stock check at a named pharmacy, confirm where the valid prescription record will remain, and obtain one next checkpoint",capabilityZh:"区分已备妥与缺货的处方项目，保留可取项目，询问药师是否允许部分领取，不要求或接受未经批准的替代品，授权联系处方方或在具名药房查询库存，确认有效处方记录保留在哪里，并取得一个后续确认节点",specimen:"Please keep the two ready items separate from the one unavailable item. If the prescription record permits a partial collection, I would like to collect only the ready items after the pharmacist's checks. I am not asking for a different product or strength. Please contact the prescriber through the recorded channel and check Cedar Pharmacy stock; do not transfer anything until I approve the named destination. Confirm where the valid prescription remains and update me under case STOCK-27 by 15:00 today.",move:"authorized prescription availability recovery"}]},{stage:37,level:"Move-in Continuity Lab",title:"Turn a new address into a verified handover",titleZh:"把新住址转成经过核验的交接",thesis:"A move becomes recoverable when the actual home and full cost are matched to the written promise before commitment, condition and access custody are recorded before belongings obscure the evidence, and address changes use verified channels with bounded forwarding rather than one uncontrolled broadcast.",thesisZh:"承诺前让实际房屋与完整费用匹配书面约定、在行李遮挡证据前记录房屋状态与门禁保管、通过经核验渠道逐项更新地址并设置有限转寄，而不是一次无控制地广播新地址，搬家过程才可恢复。",units:[{unit:1,title:"Inspect the home before committing",titleZh:"承诺前实地核验住房",capability:"Match the viewed unit and promised features, test essential access and fixtures with permission, distinguish observed facts from future repair promises, expose deposit, rent and mandatory fees, put each repair and deadline in writing, and withhold payment or signature until the final terms match",capabilityZh:"核对实看房屋与承诺特征，经允许测试必要通行和设施，区分已观察事实与未来维修承诺，完整列出押金、租金和强制费用，把每项维修及期限写入记录，并在最终条款一致前不付款或签字",specimen:"We are viewing flat 3B, the same unit named in the draft. The step-free route from the pavement to the front door is usable, the bedroom window closes, and the heating control responds, but the extractor fan does not run. Please list the fan repair with a completion date before move-in. The move-in total should show the £1,200 deposit, £1,200 first rent and every mandatory fee. We will not sign or transfer funds until the final agreement identifies this unit, the verified features, the repair and the full total.",move:"evidence-before-housing-commitment"},{unit:2,title:"Record condition and access at move-in",titleZh:"入住时记录房屋状态与门禁",capability:"Complete the inventory before unpacking, photograph and locate existing damage, test agreed fixtures, record meter identity and reading, count each key and access device, assign return responsibility, submit corrections within the stated window, and retain an acknowledged copy",capabilityZh:"在拆箱前完成清单，拍摄并定位既有损伤，测试约定设施，记录表计身份与读数，清点每把钥匙和门禁设备，明确归还责任，在规定时限内提交修正，并保留已确认副本",specimen:"Before we unpack, please add the four-centimetre scuff beside the living-room window and the chipped lower kitchen tile to the move-in inventory; our time-stamped photos show both. The lights, taps and heating work. Meter serial ending 284 reads 00631. We received two flat keys and one building fob, all to be returned at move-out. Please acknowledge these corrections today and confirm the 48-hour window for any hidden inventory issue.",move:"condition-and-access custody"},{unit:3,title:"Change address through verified channels",titleZh:"通过经核验渠道更新地址",capability:"Prioritize essential accounts, navigate independently to each official channel, disclose the new address only where required, distinguish service address, correspondence address and forwarding, set a bounded forwarding period, reject unsolicited update links, and retain dated confirmations plus a follow-up for missing mail",capabilityZh:"优先处理必要账户，独立进入每个官方渠道，只在需要处披露新地址，区分服务地址、通信地址和邮件转寄，设置有限转寄期，拒绝非请求的更新链接，并保留带日期确认及邮件缺失追踪节点",specimen:"We will update the bank, water account and broadband separately by opening each verified app or official site ourselves, not through the link in this unsolicited message. Use the new flat as the service and correspondence address only where each account requires it. Forward addressed mail from the old flat for eight weeks starting 2 October; do not forward parcels or another resident's mail. Please retain each dated confirmation and review any missing expected letter on 16 October.",move:"verified bounded address transition"}]},{stage:38,level:"Home Access Recovery Lab",title:"Restore home access without weakening security",titleZh:"在不削弱安全的情况下恢复住宅门禁",thesis:"Home access remains recoverable when key custody and official contacts are defined before failure, a lockout uses verified authority and a bounded work order rather than a bypass, and a confirmed loss ends with revoked credentials, counted replacements and a dated custody record.",thesisZh:"在故障前明确钥匙保管与官方联系人，被锁门外时使用经核验授权和有限工单而非绕过门禁，并让确认遗失最终落到凭证撤销、替代钥匙清点和带日期保管记录，住宅门禁才可恢复。",units:[{unit:1,title:"Build a recoverable home-access plan",titleZh:"建立可恢复的住宅门禁计划",capability:"Inventory issued keys and access devices without recording usable codes, name the verified building contact, authorize one spare-key custodian through the approved process, prohibit hidden communal spares, define lost-device reporting and revocation, and retain the custody confirmation",capabilityZh:"清点已发钥匙和门禁设备且不记录可用代码，注明经核验楼宇联系人，通过批准流程授权一名备用钥匙保管人，禁止在公共区域藏钥匙，定义设备遗失报告与撤销，并保留保管确认",specimen:"Our access record shows two flat keys and one building fob. Maya carries one key and the fob; Rafi carries the other key. We will verify the building desk through the resident portal, and authorize Noor as the only spare-key custodian using the building's sealed handover process—nothing will be hidden outside or in a shared area. If a key or fob is lost, we will report the exact item immediately, ask the desk to revoke any electronic credential, and retain the updated custody reference.",move:"bounded home-access custody"},{unit:2,title:"Authorize a lockout service before work begins",titleZh:"开工前授权被锁门外服务",capability:"Wait in a safe shared place, contact the building or covered provider through an independently verified channel, present only required residence and identity evidence privately, confirm the exact door and authority without sharing codes, obtain callout, labour, parts and total ceiling, require approval before scope changes, and retain the work reference",capabilityZh:"在安全公共区域等候，通过独立核验渠道联系物业或保障服务商，私密出示所需住址与身份凭证，在不分享代码的情况下确认准确房门与权限，取得上门、人工、零件和总价上限，要求范围变化前再次批准，并保留工单编号",specimen:"We are waiting in the staffed lobby and will not try to bypass the door. I contacted the building's approved provider through the resident portal. At the desk I can privately show photo ID and the tenancy record for flat 3B, but I will not disclose alarm or access codes. Before work begins, please confirm technician ID, work order LOCK-42, the £75 callout, £45 labour, no parts currently authorized, and a £120 total ceiling. Stop and ask before any new part, damage or higher total.",move:"verified bounded lockout authorization"},{unit:3,title:"Close key loss with new custody",titleZh:"以新的保管记录闭环钥匙遗失",capability:"Identify the confirmed lost credential and report time, revoke electronic access promptly, have the authorized manager and locksmith decide the necessary security change, preserve unaffected credentials only when confirmed, count and assign every replacement, test normal authorized access, and retain a dated completion receipt and updated inventory",capabilityZh:"识别确认遗失的凭证与报告时间，及时撤销电子通行，由获授权管理方与锁匠决定必要安全变更，仅在确认后保留未受影响凭证，清点并分配每个替代品，测试正常授权通行，并保留带日期完工收据与更新清单",specimen:"Rafi confirmed at 18:10 that key two and fob B were lost together. The building desk revoked fob B under incident ACCESS-63. The manager and approved locksmith will determine the required lock change; we are not requesting a shortcut. After completion, please count two new flat keys and replacement fob C, assign key one to Maya and key two plus fob C to Rafi, test the door and fob with us present, and issue a dated receipt plus updated access inventory showing the old credentials closed.",move:"lost-credential security closure"}]},{stage:39,level:"Airport Journey Continuity Lab",title:"Keep the traveler, assistance and baggage on one route",titleZh:"让旅客、协助与行李保持在同一条路线",thesis:"An airport journey stays recoverable when the full itinerary, document readiness, assistance and baggage rules are confirmed before purchase, checked-bag custody is fixed at handoff, and a broken connection is replaced by one explicit route that also moves assistance and baggage.",thesisZh:"购票前确认完整行程、证件准备、协助与行李规则，托运行李交接时固定保管记录，并在衔接中断后用一条同时迁移协助和行李的明确路线替代旧路线，机场出行才可恢复。",units:[{unit:1,title:"Verify the whole airport journey before paying",titleZh:"付款前核验完整机场行程",capability:"Match traveler names privately to document-ready spellings, confirm departure, connection and arrival airports with local dates and times, test the connection against mobility assistance, separate cabin and checked baggage rules, expose seat and mandatory fees, and retain one itinerary plus assistance reference",capabilityZh:"私密匹配旅客姓名与证件拼写，确认出发、中转和到达机场及当地日期时间，按行动协助检验衔接，区分随身和托运行李规则，列出座位与强制费用，并保留一份行程及协助编号",specimen:"Before payment, please confirm Maya Chen and Rafi Noor match the document-ready spellings shown privately. The journey leaves Northport at 08:20 on 14 May, connects at Harbor Terminal for two hours ten minutes, and reaches Cedar City at 16:40 local time. Assistance ASSIST-51 must meet us at departure, the connection and arrival. Each traveler has one cabin bag; we share one 20-kilogram checked bag. Please show the selected seats, every mandatory fee, full total, baggage rules and one itinerary confirmation.",move:"pre-payment whole-journey verification"},{unit:2,title:"Check a bag into attributable custody",titleZh:"让托运行李进入可归属保管",capability:"Match the traveler and confirmed itinerary at the staffed counter, describe the distinctive bag without exposing document details, verify weight and accepted contents, check tag destination and connection before release, keep the claim receipt separate, observe official-belt acceptance, and retain the handoff reference",capabilityZh:"在人工柜台匹配旅客与已确认行程，在不暴露证件细节的情况下描述醒目行李，核验重量与可接受内容，在放行前检查标签目的地和衔接，将提取凭据分开保管，观察官方传送带接收，并保留交接编号",specimen:"This is our one checked bag: a deep-teal hard-shell case with an ochre strap, 17.4 kilograms, with no spare batteries or prohibited items inside. Please match it to Rafi Noor's confirmed itinerary without reading document details aloud. Before it leaves us, confirm the tag shows Cedar City through Harbor Terminal. I will keep claim receipt BAG-62 separately. The staffed belt has accepted the case; please record the handoff time as 06:48.",move:"tagged checked-bag custody"},{unit:3,title:"Recover a missed connection as one journey",titleZh:"把误机衔接恢复成一条行程",capability:"Confirm the inbound delay and closed connection, use the official transfer desk, compare a complete replacement route rather than isolated segments, restore confirmed assistance and seat needs, trace and reroute the checked bag, obtain bounded meal or overnight support when applicable, close the old path, and retain one update reference",capabilityZh:"确认入境延误与已关闭衔接，使用官方中转柜台，比较完整替代路线而非孤立航段，恢复已确认协助与座位需求，追踪并改送托运行李，在适用时取得有限餐食或过夜支持，关闭旧路径，并保留一个更新编号",specimen:"The inbound flight arrived at 14:35, after our 14:10 Cedar City connection closed. At the official transfer desk, please replace the old path with the confirmed 18:20 flight arriving 21:05 today, not two unlinked reservations. Restore assistance ASSIST-51 from this desk to the gate and on arrival, keep our adjacent seats, and reroute checked bag BAG-62 to the same flight. Please close the missed segment, confirm the meal allowance, and issue journey case CONNECT-38 with the next update at 16:30.",move:"single-path airport recovery"}]},{stage:40,level:"Hotel Checkout Continuity Lab",title:"Close a hotel stay without losing custody or money",titleZh:"在不丢失保管与资金状态的情况下结束酒店住宿",thesis:"A hotel stay closes reliably when temporary luggage custody is attributable, the itemized folio separates valid charges, disputes and authorization holds before payment, and returned keys, room condition, final receipt and hold release each receive an explicit closing state.",thesisZh:"临时行李寄存可归属、付款前在明细账中区分有效消费、争议项目与预授权冻结，并让钥匙归还、房间状态、最终收据和冻结解除分别获得明确闭环，酒店住宿才能可靠结束。",units:[{unit:1,title:"Store luggage under attributable custody",titleZh:"让退房后行李进入可归属保管",capability:"Use a staffed desk, count and distinguish every bag, record starting condition, exclude valuables, attach matched custody tags, name the authorized collector and collection deadline, and retain a claim receipt until physical collection",capabilityZh:"使用人工柜台，清点并区分每件行李、记录起始状态、排除贵重物品、附上匹配保管标签、注明获授权领取人和截止时间，并把提取凭据保留到实际领取",specimen:"Please store these two bags at the staffed luggage desk after our 11:00 checkout: one deep-teal hard-shell case with an ochre strap and one navy backpack with a white handle tag. Both are closed and undamaged; passports, medication, devices and payment cards stay with us. Please attach two numbered custody tags, give Maya the paired claim receipt, release them only to Maya after matching the receipt, and confirm collection by 18:00 today under STORE-42.",move:"tagged temporary luggage custody"},{unit:2,title:"Reconcile the folio before settling",titleZh:"结算前逐项核对住宿账单",capability:"Match the folio to the stay, validate each line and tax, isolate a duplicate or disputed charge without rejecting valid items, distinguish the temporary card authorization from settled payment, obtain a corrected total, choose the payment method, and retain an itemized receipt",capabilityZh:"把账单与住宿匹配，核验每项消费和税费，在不否定有效项目的情况下隔离重复或争议收费，区分临时银行卡预授权与已结算付款，取得修正总额、选择付款方式并保留明细收据",specimen:"Please review folio STAY-62 before charging the card. The two room nights at £96, £18 breakfast, £24 café charge and £12 tax match; the £24 café line appears twice although we signed once. Please remove only the duplicate and show the corrected total of £246. The separate £150 authorization is a temporary hold, not another settled charge; confirm its current status and expected release. We will pay the corrected £246 by the card ending 42 and need the itemized receipt.",move:"folio-before-payment reconciliation"},{unit:3,title:"Close keys, room balance and card hold",titleZh:"闭环钥匙、房账与银行卡冻结",capability:"Return and count every room key, distinguish pre-existing condition from new damage, close the room and booking, confirm the final paid balance with a dated receipt, preserve a separate authorization-release amount and deadline plus one trace route, and keep any luggage claim open until collection",capabilityZh:"归还并清点每张房卡，区分既有状态与新增损伤，关闭房间与预订，用带日期收据确认最终已付余额，另行保留预授权解除金额、期限和一个追查渠道，并让行李提取状态保持开放直到领取",specimen:"At 11:05 we returned both room key cards at the staffed desk. The room inventory matches checkout apart from the two-centimetre desk mark already recorded at arrival. Please close the room and booking, confirm the final balance of £246 paid, and issue dated receipt CLOSE-58. The separate £150 card hold should be released within five working days; if it remains after 27 May, trace it under HOLD-31. Keep luggage claim STORE-42 open until we collect both bags by 18:00.",move:"multi-state hotel checkout closure"}]},{stage:41,level:"Restaurant Meal Continuity Lab",title:"Keep a restaurant meal safe, specific and settled",titleZh:"让餐厅用餐从订位到结账都安全、明确且闭环",thesis:"A restaurant meal stays reliable when the reservation carries real seating needs without pretending to settle food safety, the table order turns allergies and substitutions into a kitchen-confirmed decision, and the final bill separates valid items, corrections, shares and gratuity before payment.",thesisZh:"订位时记录真实座位需求但不假装已经解决食品安全，桌边点餐把过敏与替代转成厨房确认的决定，并在付款前区分有效项目、修正、各自份额与小费，餐厅用餐才可靠。",units:[{unit:1,title:"Reserve the table and preserve the seating promise",titleZh:"订位并保留座位承诺",capability:"Name the date, arrival time and party size, confirm a step-free route and one specific seating need, define the hold window and late-arrival contact, record a dietary alert without treating it as a safety guarantee, require table-side reconfirmation, and retain the reservation reference",capabilityZh:"说明日期、到达时间和人数，确认无台阶路线与一个具体座位需求，定义保留时限和迟到联系，记录饮食提醒但不把它当作安全保证，要求桌边再次确认，并保留订位编号",specimen:"Please reserve a table for Maya and Rafi, two people, at 18:30 on 12 June. We need a step-free route from the entrance and a quieter table away from the service aisle. Please hold it for fifteen minutes and call the verified number if our arrival is delayed. Add a severe sesame-allergy alert, but do not mark any dish safe yet; the server must confirm ingredients and kitchen controls with us at the table. Please send reservation reference TABLE-46 with these seating notes.",move:"reservation-to-seating continuity"},{unit:2,title:"Confirm an allergy-aware order without guessing",titleZh:"不靠猜测确认过敏友好点餐",capability:"State the allergen and severity, identify the exact dish, ask the server to check ingredients and cross-contact controls with the kitchen, distinguish removal from safe preparation, pause an unapproved substitution, approve one confirmed alternative, require an order read-back and allergen flag, and stop the order if safety cannot be confirmed",capabilityZh:"说明过敏原与严重程度，识别准确菜品，请服务员向厨房核验配料与交叉接触控制，区分去除配料与安全制作，暂停未经批准的替代，只批准一个已确认选项，要求复述订单和过敏标记，并在无法确认安全时停止下单",specimen:"I have a severe sesame allergy. I would like the grilled vegetable rice bowl, but please ask the kitchen to check the marinade, garnish and shared preparation surfaces; removing visible seeds alone is not enough. Do not substitute the house sauce without asking. If the kitchen confirms the plain lemon dressing and separately cleaned utensils are suitable, I approve that change. Please read the final dish and dressing back, mark the allergy on the order, and stop rather than guess if any control cannot be confirmed.",move:"kitchen-confirmed allergy order"},{unit:3,title:"Reconcile, split and close the restaurant bill",titleZh:"核对、分账并闭环餐厅账单",capability:"Match every valid item to the table, isolate an incorrect duplicate before payment, confirm the corrected subtotal and any mandatory service charge, split named items and shared items by an exposed rule, add voluntary gratuity exactly once, authorize separate final amounts, and retain separate itemized receipts",capabilityZh:"把每个有效项目与餐桌匹配，付款前隔离错误重复项，确认修正小计及任何强制服务费，按可见规则拆分各自与共享项目，只添加一次自愿小费，分别授权最终金额，并保留各自明细收据",specimen:"Before payment, please review bill MEAL-38. Maya's £14 bowl, Rafi's £16 plate and the shared £6 drink are correct; the £7 dessert appears twice although we ordered one. Remove only the duplicate and confirm the corrected £43 subtotal with no mandatory service charge. Split the drink equally: Maya's item share is £24 and Rafi's is £19. We will each add a 10% voluntary tip once to our own amount, pay separately, and need two itemized receipts showing the correction, split and gratuity.",move:"itemized split-bill settlement"}]},{stage:42,level:"Outpatient Visit Continuity Lab",title:"Carry one clinical story from check-in to follow-up",titleZh:"让同一条临床信息从到诊延续到复诊",thesis:"An outpatient visit remains safe and recoverable when triage receives observable change rather than a self-diagnosis, examinations and specimens move only after informed confirmation and attributable matching, and discharge separates the working assessment, home plan, warning signs, pending results and follow-up ownership.",thesisZh:"分诊接收可观察变化而非自行诊断，检查与样本只在知情确认和可归属匹配后推进，离院安排则区分初步判断、居家计划、警示症状、待出结果与复诊责任，门诊就医才安全且可恢复。",units:[{unit:1,title:"Check in with an observable triage story",titleZh:"用可观察信息完成到诊分诊",capability:"Confirm identity privately, state the main symptom with onset, baseline, change, severity and functional effect, report medicines already taken and allergies, answer red-flag questions directly without diagnosing, identify the current waiting location, and define how any urgent change will be escalated",capabilityZh:"私密确认身份，说明主要症状的起始、平时基线、变化、程度与功能影响，报告已服药物和过敏，直接回答危险信号问题而不自行诊断，说明当前等候位置，并定义紧急变化如何升级",specimen:"Please verify my identity privately at the desk. Since 07:00 yesterday, I have had a steady pain in the lower right abdomen; it was 3 out of 10 then and is 6 now, and walking makes it worse. I vomited once at 05:30 today and have kept down small sips since. I took one labelled dose of paracetamol at 06:00, take no regular medicine, and am allergic to penicillin. I have not fainted and there is no heavy bleeding. I will wait in bay C; if the pain suddenly rises, I faint or cannot keep fluids down, I will tell the nurse immediately rather than guess the cause.",move:"observation-to-triage handoff"},{unit:2,title:"Confirm the examination and specimen before they move",titleZh:"在检查与样本推进前完成确认",capability:"Ask the purpose and sequence of the proposed examination and tests, clarify discomfort, preparation, limits and alternatives, distinguish recommendation from consent, pause optional work until questions are answered, verify the specimen label against private identifiers in the patient's presence, observe sealing and destination, and retain the collection reference",capabilityZh:"询问拟议检查和检验的目的与顺序，澄清不适、准备、局限与替代方案，区分建议与同意，在问题回答前暂停可选项目，在患者在场时用私密身份信息核验样本标签，观察封口与去向，并保留采集编号",specimen:"Before we begin, please explain why you recommend the abdominal examination and blood test, what each involves, what discomfort to expect and what they cannot show. I consent to those two after my questions are answered; please pause the optional scan until the clinician explains its purpose, alternatives and urgency. For the blood tube, compare the label with my two private identifiers while I am present, show me that it is sealed for the clinic laboratory, and record collection reference SAMPLE-64. My consent to the blood test does not automatically include the scan.",move:"consent-to-specimen custody"},{unit:3,title:"Leave with results and follow-up ownership",titleZh:"带着结果与复诊责任离院",capability:"Separate the working assessment from confirmed findings, read back home-care and medicine instructions, name specific warning signs and the correct urgent route, identify every pending result with its verified delivery channel and deadline, assign who will review and contact, book the follow-up or define its trigger, and retain one visit reference",capabilityZh:"区分初步判断与已确认结果，复述居家照护与用药说明，说明具体警示症状和正确紧急渠道，列出每项待出结果及经核验的送达渠道和期限，明确由谁审核与联系，预约复诊或定义触发条件，并保留一个就诊编号",specimen:"My understanding is that the examination is reassuring, but the cause is still a working assessment until the blood result returns. At home I will drink small amounts regularly and take the labelled medicine only as written. If I faint, the pain becomes severe, I develop heavy bleeding or cannot keep fluids down, I will use the urgent route you named rather than wait for a message. The clinic will post the blood result in the verified portal by 16:00 tomorrow; Dr Lin's team will review it and call if action is needed. My follow-up is Friday at 10:20 under VISIT-52. Please correct my read-back and give me the written plan.",move:"discharge-to-result continuity"}]},{stage:43,level:"Rental Car Continuity Lab",title:"Keep a rental car attributable from counter to return",titleZh:"让租车从柜台到归还始终可归属",thesis:"A rental remains recoverable when drivers, operating rules, protection choices, mandatory costs and the card hold are fixed before payment, the exact vehicle and starting condition are evidenced before custody moves, and return closes mileage, fuel, access items, condition, final charges and hold release as separate states.",thesisZh:"付款前固定驾驶人、使用规则、保障选择、强制费用和银行卡冻结，在保管转移前为准确车辆与起始状态留证，并在归还时分别关闭里程、燃油、门禁物品、车况、最终收费和冻结解除，租车过程才可恢复。",units:[{unit:1,title:"Confirm the whole rental before payment",titleZh:"付款前确认完整租车安排",capability:"Confirm the primary and additional driver, exact pickup and return place and time, vehicle class, mileage, fuel and toll rules, selected protection and excess, roadside route, every mandatory fee and estimated total, distinguish the authorization hold from settled charges, reject unapproved extras, and retain one agreement reference",capabilityZh:"确认主驾驶与附加驾驶人、准确取还地点和时间、车型、里程、燃油与通行费规则、所选保障和免赔额、道路救援渠道、所有强制费用和预计总额，区分预授权冻结与已结算收费，拒绝未经批准的附加项，并保留一个协议编号",specimen:"Before payment, please confirm rental DRIVE-48: Maya is the primary driver and Rafi the only additional driver. We collect a compact automatic here at 09:00 on 6 July and return it here by 17:00 on 9 July. The rate includes unlimited mileage, a full-to-full fuel rule and tolls billed only from the registered tag. We accept the stated collision protection with a £500 excess and no other add-ons. Please show the roadside route, £186 rental total with every mandatory fee, and the separate £250 card authorization hold with its release terms before we authorize payment.",move:"pre-payment rental verification"},{unit:2,title:"Record the exact vehicle before taking custody",titleZh:"接管前记录准确车辆状态",capability:"Match the vehicle identifier and class to the agreement, photograph and locate every existing mark before moving the car, record fuel, odometer and dashboard state, count keys and remotes, test safety-critical lights, tires and warning indicators while stationary, obtain agent acknowledgement on the condition record, and accept custody only after corrections are saved",capabilityZh:"把车辆标识和车型与协议匹配，在移动车辆前拍摄并定位每处既有痕迹，记录燃油、里程表与仪表状态，清点钥匙和遥控器，在静止状态测试关键灯光、轮胎和警示指示，取得工作人员对车况记录的确认，并只在修正保存后接管",specimen:"Before we move the car, please match vehicle identifier ending 284 and the compact automatic class to DRIVE-48. Add the six-centimetre scratch on the right rear door and the small mark on the front-left wheel to the pickup record with our time-stamped photos. The odometer is 24,610 miles, fuel is full and no dashboard warning is lit. We received one key and one remote. With the engine stationary, the headlights, indicators and brake lights work, and all four tires appear inflated. Please acknowledge the corrected condition record before Maya accepts custody.",move:"evidenced vehicle custody"},{unit:3,title:"Return the car and close every open state",titleZh:"还车并关闭每个开放状态",capability:"Use the authorized return bay and deadline, record odometer and agreed fuel state, count keys and remotes, preserve time-stamped condition evidence and compare it to pickup, obtain staffed acceptance, reconcile rental, toll and fuel lines without inventing damage, confirm the final settled total separately from the authorization hold, define the hold-release deadline and trace route, and retain a closing receipt",capabilityZh:"使用获授权归还区并遵守期限，记录里程与约定燃油状态，清点钥匙和遥控器，保留带时间车况证据并与取车记录比较，取得人工接收，核对租金、通行费和燃油项目且不虚构损伤，分别确认最终已结算总额与预授权冻结，定义冻结解除期限和追查路径，并保留关闭收据",specimen:"At 16:35 on 9 July, we parked in the staffed return bay before the 17:00 deadline. The odometer is 24,842 miles and the tank is full; here are the final fuel receipt and time-stamped photos. We returned one key and one remote. The right rear-door scratch and front-left wheel mark match the acknowledged pickup record, with no new damage observed. Please close DRIVE-48 at the valid £186 rental plus £9 registered toll, issue the £195 itemized final receipt, and release the separate £250 card hold within five working days. If it remains after 16 July, trace it under RETURN-63.",move:"multi-state rental return closure"}]},{stage:44,level:"Identity Document Renewal Lab",title:"Keep a document renewal private and traceable",titleZh:"让证件续期保持私密且可追踪",thesis:"A document renewal stays recoverable when requirements, timing and fees are verified through an independently reached official route, every original and biometric step has bounded purpose and custody at submission, and tracking and collection end with the new document checked, the old document's state explicit, and a durable correction route.",thesisZh:"通过独立进入的官方渠道核验要求、时间与费用，提交时让每份原件和生物信息步骤都有有限目的与保管记录，并在追踪和领取时核验新证件、明确旧证件状态和持久纠错渠道，证件续期才可恢复。",units:[{unit:1,title:"Verify the renewal route before sharing documents",titleZh:"提交证件前核验续期渠道",capability:"Navigate independently to the official route, confirm renewal type and eligibility, appointment office and time, distinguish originals from accepted copies, verify photo and accessibility requirements, expose the exact fee and payment method, compare processing time with any real deadline without assuming priority, retain cancellation and rescheduling rules, and reject unsolicited document-upload links",capabilityZh:"独立进入官方渠道，确认续期类型与资格、预约办公室和时间，区分原件与可接受副本，核验照片与无障碍要求，显示准确费用和付款方式，把办理时间与真实期限比较但不假设优先处理，保留取消和改约规则，并拒绝非请求证件上传链接",specimen:"I opened the official portal independently rather than using the message link. Please confirm this is a standard adult renewal appointment at Central Office at 09:40 on 8 October. The checklist requires the current document and one address original; a plain copy is accepted for the appointment letter. The portrait must meet the stated size and background rules. Please confirm step-free access, the £72 fee paid only at submission, the ten-working-day estimate, and the cancellation route. I travel on 30 October, but I am not assuming priority service. I will keep checklist reference READY-58 and upload nothing through the unsolicited message.",move:"verified renewal preparation"},{unit:2,title:"Submit originals and biometrics into bounded custody",titleZh:"让原件与生物信息进入有限保管",capability:"Verify identity privately at the staffed counter, inventory every original and copy before transfer, distinguish inspected-and-returned from retained items, ask the purpose and retention of portrait, signature or biometric capture before consent, review the application summary before submission, authorize only the stated fee, and retain a receipt connecting retained custody, application reference and next update",capabilityZh:"在人工柜台私密核验身份，转移前清点每份原件与副本，区分查验后返还和留存项目，在同意前询问照片、签名或生物信息采集的目的与保留方式，提交前审阅申请摘要，只授权所列费用，并保留连接留存保管、申请编号和下次更新的收据",specimen:"At this staffed counter, please verify my details privately. I am presenting the current document, one address original and the appointment-letter copy. Return the address original after inspection; retain the current document only under the recorded renewal rule. Before the portrait and fingerprint capture, explain their purpose, how they attach to this application and the stated retention. I consent only to those renewal steps. Let me review the application summary before submission, then charge the stated £72 once. Please issue receipt APPLY-64 showing the retained document, fee, application reference and status update by 16:00 Friday.",move:"bounded document-and-biometric custody"},{unit:3,title:"Collect the new document and close the old state",titleZh:"领取新证件并关闭旧证件状态",capability:"Use the verified tracking channel, distinguish dispatched, ready and collected states, follow the authorized collector rule without exposing reusable credentials, match the sealed document privately, inspect identity fields, portrait and validity before leaving, resolve any mismatch without activating or using the document, confirm whether the old document is returned, cancelled or retained, close collection or delivery, and retain the final receipt plus correction route",capabilityZh:"使用经核验追踪渠道，区分已寄出、可领取和已领取状态，遵守获授权领取规则且不暴露可复用凭证，私密匹配密封证件，离开前核验身份字段、照片和有效期，发现不符时在不激活或使用证件的情况下处理，确认旧证件是返还、注销还是留存，关闭领取或投递，并保留最终收据与纠错渠道",specimen:"The verified portal shows application APPLY-64 ready for collection, not already collected. At the staffed desk I will show the required claim receipt and identity evidence privately. Before I leave, please open the sealed handoff with me so I can check the name spelling, portrait and validity dates without reading them aloud. If any field differs from the approved summary, do not activate the document; open a correction case. Please return the old document visibly cancelled as the receipt specifies, close collection at today's time, and issue final receipt COLLECT-39 with the correction contact.",move:"new-to-old identity state closure"}]},{stage:45,level:"Dental Visit Continuity Lab",title:"Carry a dental visit from symptom to safe follow-up",titleZh:"让牙科就诊从症状延续到安全复诊",thesis:"Dental care stays understandable when booking preserves an observable symptom timeline and urgent route, treatment begins only after the exact site, finding, options and consent boundary are understood, and departure separates expected recovery from escalation while follow-up and billing remain attributable.",thesisZh:"预约时保留可观察的症状时间线和紧急路径，治疗仅在准确部位、发现、选项与同意边界均被理解后开始，离院时区分预期恢复与升级情形，同时让复诊和收费可追溯，牙科护理才保持可理解。",units:[{unit:1,title:"Book and check in with an observable dental story",titleZh:"用可观察的牙科叙述预约并到诊",capability:"Describe exact location, onset, change, triggers, severity and function without diagnosing, disclose labelled medicine and allergies, answer urgent warning questions directly, confirm named appointment, access and private identity check-in, and retain a route for worsening before arrival",capabilityZh:"不自行诊断地描述准确位置、起始、变化、诱因、程度和功能，披露按标签服用的药物与过敏信息，直接回答紧急警示问题，确认具名预约、无障碍与私密身份核验，并保留到诊前恶化路径",specimen:"The pain is around my lower-left back tooth. It began two days ago at 2 out of 10, is now 5, and chewing or cold water makes it worse; I can still drink and open my mouth normally. I took one labelled dose of paracetamol at 08:00, take no regular medicine and have a latex allergy. I have no facial swelling, fever, heavy bleeding or trouble breathing or swallowing. Please confirm my 10:30 appointment with Dr Shah today, step-free access and private identity check-in under DENT-41. If swelling, breathing difficulty, uncontrolled bleeding or rapid worsening starts before I arrive, I will use the urgent dental route immediately.",move:"observable dental booking and escalation"},{unit:2,title:"Confirm the finding and consent boundary before treatment",titleZh:"治疗前确认发现与同意边界",capability:"Match the patient and exact tooth privately, distinguish an observable examination or image finding from certainty, ask the purpose and sequence of the proposed procedure, expected sensations, material risks, alternatives and deferral consequences, agree a stop signal, authorize only named treatment and anaesthetic, keep extras paused, and retain a written summary",capabilityZh:"私密匹配患者与准确牙位，把可观察检查或影像发现与确定性区分，询问拟议操作的目的与顺序、预期感受、重要风险、替代方案与推迟后果，约定停止信号，只授权具名治疗与麻醉，暂停额外项目，并保留书面摘要",specimen:"Please match the lower-left first molar to my record and show me the examination image. My understanding is that you observed a small cavity, not that every source of pain is proven. Before we begin, explain the purpose and sequence of the local anaesthetic and filling, expected pressure or vibration, material risks, the alternative of monitoring and what delay could change. Raising my left hand means pause. I consent only to the anaesthetic and filling on that tooth today; whitening and any additional work remain paused. Please give me the written treatment summary CONSENT-52.",move:"site-specific bounded dental consent"},{unit:3,title:"Leave with safe aftercare, follow-up and a closed bill",titleZh:"带着安全护理、复诊与闭环账单离院",capability:"Read back expected numbness and time-bounded precautions, follow only labelled medicine directions, distinguish urgent swelling, breathing, swallowing, bleeding or worsening pain from expected recovery, name the urgent contact route, assign follow-up owner and time, reconcile agreed treatment with the itemized final bill, reject unauthorized extras, and retain payment and correction references",capabilityZh:"复述预期麻木与有时限的注意事项，只遵循药品标签说明，把紧急肿胀、呼吸、吞咽、出血或疼痛恶化与预期恢复区分，说明紧急联系路径，分配复诊负责人和时间，把约定治疗与明细最终账单核对，拒绝未授权额外项目，并保留付款与纠错编号",specimen:"My read-back is that numbness should fade in a few hours; until normal feeling returns I will avoid chewing, hot drinks and driving, and I will take the labelled pain medicine only as written. I will call the urgent dental line now for increasing facial swelling, trouble breathing or swallowing, bleeding that will not stop or rapidly worsening pain. The clinic will review healing at 09:20 on 18 May under FOLLOW-63. The £215 final bill contains only the agreed examination, image and filling, with no whitening charge. Please issue receipt PAY-74 and keep correction case route BILL-28.",move:"dental recovery and settlement closure"}]}];u.reduce((a,t)=>a+t.units.length,0);const v="_root_11r2v_1",w="_header_11r2v_2",k="_kicker_11r2v_2",Z="_desk_11r2v_3",x="_paper_11r2v_3",I="_margin_11r2v_3",C="_note_11r2v_3",T="_comparison_11r2v_4",P="_start_11r2v_5",M="_scenarioRail_11r2v_6",R="_stages_11r2v_7",L="_stageMeta_11r2v_7",j="_progress_11r2v_10",i={root:v,header:w,kicker:k,desk:Z,paper:x,margin:I,note:C,comparison:T,start:P,scenarioRail:M,stages:R,stageMeta:L,progress:j},A={"zh-CN":{title:"英语不是更长的词表，而是更精确的选择",description:"英语课程拥有独立的编辑型路线：比较版本、标注话语效果，再在真实段落里重写。",deskLabel:"英语编辑工作台示意图",merelyCorrect:"普通正确",calibrated:"专家校准",openFirst:"进入第一节精修课",continueAt:(a,t)=>`继续 Stage ${a} · 第 ${t} 课`,progress:(a,t)=>`已完成 ${a}/${t} 节`,scenariosLabel:"英语日常生活场景",scenes:["会议","邮件","分歧","投诉","修复","边界"],done:"✓ 已完成",open:"已开放"},en:{title:"Advanced English is the quality of your choices",description:"English follows its own editorial path: compare versions, annotate their effects, then rewrite inside a real paragraph.",deskLabel:"English editorial workbench illustration",merelyCorrect:"Merely correct",calibrated:"Expertly calibrated",openFirst:"Open the first mastery lesson",continueAt:(a,t)=>`Continue with Stage ${a} · Unit ${t}`,progress:(a,t)=>`${a} of ${t} lessons complete`,scenariosLabel:"Everyday English scenarios",scenes:["Meeting","Email","Disagree","Service","Repair","Boundary"],done:"✓ done",open:"open"},id:{title:"Bahasa Inggris tingkat lanjut adalah soal ketepatan pilihan",description:"Bahasa Inggris punya jalur editorial sendiri: bandingkan versi, tandai efeknya, lalu tulis ulang di dalam paragraf nyata.",deskLabel:"Ilustrasi meja editorial bahasa Inggris",merelyCorrect:"Sekadar benar",calibrated:"Ditakar seperti ahli",openFirst:"Buka pelajaran mastery pertama",continueAt:(a,t)=>`Lanjutkan Stage ${a} · Unit ${t}`,progress:(a,t)=>`${a} dari ${t} pelajaran selesai`,scenariosLabel:"Skenario bahasa Inggris sehari-hari",scenes:["Rapat","Email","Beda pendapat","Keluhan","Memperbaiki","Batasan"],done:"✓ selesai",open:"terbuka"},ja:{title:"上級英語とは、より的確な言葉を選べること",description:"英語には独自の編集型ルートがあります。複数の版を比べ、表現の効果に注釈をつけ、実際の段落の中で書き直します。",deskLabel:"英語の編集デスクのイラスト",merelyCorrect:"ただ正しいだけ",calibrated:"専門家レベルに調整",openFirst:"最初のマスタリーレッスンを開く",continueAt:(a,t)=>`Stage ${a} · Unit ${t} を続ける`,progress:(a,t)=>`${a}/${t} レッスン完了`,scenariosLabel:"日常の英語シーン",scenes:["会議","メール","意見の相違","苦情","関係修復","境界線"],done:"✓ 完了",open:"公開中"}},S=[{icon:"◌",key:"meeting"},{icon:"✉",key:"email"},{icon:"⇄",key:"disagree"},{icon:"⌂",key:"service"},{icon:"↶",key:"repair"},{icon:"│",key:"boundary"}];function B({locale:a="en"}){const t=m(a),l=t==="zh-CN",r=A[t],[c]=y.useState(f),s=b(c),d=Math.min(c.size,p);return e.jsxs("section",{className:i.root,"aria-labelledby":"english-mastery-title",children:[e.jsxs("header",{className:i.header,children:[e.jsxs("div",{children:[e.jsx("p",{className:i.kicker,children:"English Mastery · B1–C2+"}),e.jsx("h2",{id:"english-mastery-title",children:r.title}),e.jsx("p",{children:r.description})]}),e.jsxs("div",{className:i.desk,"aria-label":r.deskLabel,children:[e.jsx("span",{className:i.margin,children:"stance"}),e.jsxs("div",{className:i.paper,children:[e.jsx("i",{}),e.jsx("i",{}),e.jsx("i",{}),e.jsx("strong",{children:"suggests ≠ proves"}),e.jsx("i",{}),e.jsx("i",{})]}),e.jsx("span",{className:i.note,children:"scope?"})]})]}),e.jsxs("div",{className:i.comparison,children:[e.jsx("span",{children:r.merelyCorrect}),e.jsx("p",{children:"The results prove the policy works."}),e.jsx("span",{children:r.calibrated}),e.jsx("p",{children:"The results suggest the policy helped under the conditions tested."}),d===0||!s?e.jsx(h,{className:i.start,to:"/english-mastery?stage=2&unit=1",children:r.openFirst}):e.jsx(h,{className:i.start,to:`/english-mastery?stage=${s.stage}&unit=${s.unit}`,children:r.continueAt(s.stage,s.unit)}),d>0&&e.jsx("small",{className:i.progress,children:r.progress(d,p)})]}),e.jsx("div",{className:i.scenarioRail,"aria-label":r.scenariosLabel,children:S.map((n,o)=>e.jsxs("figure",{children:[e.jsx("span",{children:n.icon}),e.jsx("figcaption",{children:r.scenes[o]})]},n.key))}),e.jsx("div",{className:i.stages,children:u.map(n=>e.jsxs("article",{children:[e.jsxs("div",{className:i.stageMeta,children:[e.jsxs("span",{children:["Stage ",n.stage]}),e.jsx("strong",{children:n.level})]}),e.jsx("h3",{children:l?n.titleZh:n.title}),e.jsx("p",{children:l?n.thesisZh:n.thesis}),e.jsx("ol",{children:n.units.map(o=>e.jsxs("li",{children:[e.jsx("span",{children:o.unit}),e.jsxs("div",{children:[e.jsx("strong",{children:e.jsx(h,{to:`/english-mastery?stage=${n.stage}&unit=${o.unit}`,children:l?o.titleZh:o.title})}),e.jsx("small",{children:l?o.capabilityZh:o.capability})]}),g(c,{stage:n.stage,unit:o.unit})?e.jsx("em",{"data-complete":"true",children:r.done}):e.jsx("em",{children:r.open})]},o.unit))})]},n.stage))})]})}export{B as EnglishMasteryPathVisual};
